import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { api } from '../../lib/api';
import { useLocations } from '../../hooks/useLocations';
import { useQBContext } from '../../contexts/QBContext';
import { useQuickBooks } from '../../hooks/useQuickBooks';
import { useToast } from '../Toast';
import { ErrorCard, DashboardSkeleton, EmptyState } from '../shared';
import MappingFilters from './MappingFilters';
import MappingTable from './MappingTable';
import ProductMappingSection from './ProductMappingSection';
import { BILL_FIELD_LABELS, TRANSACTION_TYPE_LABELS, TRANSACTION_TYPES, VENDOR_CREDIT_FIELD_LABELS } from '../../../types';
import type { ColumnMapping, ExcelParseResult, Mapping, MappingSuggestion, ScanData, ScanEntry, TabId, ExportTemplate, Template } from '../../../types';
import type { QBAccount } from '../../types/qb';
import type { SelectOption } from '../SearchableSelect';

/**
 * Validates that a posting type is consistent with an account type.
 * Returns null if valid, or a warning string if potentially incorrect.
 *
 * Basic accounting rules:
 * - Debit INCREASES: Asset, Expense
 * - Credit INCREASES: Liability, Equity, Income
 *
 * This is advisory only — some edge cases (contra accounts, draws, voids) are valid exceptions.
 */
export function validateMappingAccountType(
  accountType: string | undefined,
  postingType: 'Debit' | 'Credit',
): string | null {
  if (!accountType) return null;

  const debitIncreases = ['Asset', 'Expense'];
  const creditIncreases = ['Liability', 'Equity', 'Income'];

  if (postingType === 'Debit' && creditIncreases.includes(accountType)) {
    return `Debit decreases ${accountType} accounts — typically you'd Credit ${accountType} accounts.`;
  }

  if (postingType === 'Credit' && debitIncreases.includes(accountType)) {
    return `Credit decreases ${accountType} accounts — typically you'd Debit ${accountType} accounts.`;
  }

  return null;
}

export interface LocalMapping {
  localId: string;
  remoteId?: string;
  templateId?: string | null;
  sourceField: string;
  accountId: string;
  postingType: 'Debit' | 'Credit';
  description: string;
  classId: string;
  taxCodeId: string;
  entityType: '' | 'customer' | 'vendor' | 'employee';
  entityId: string;
  amountRule: string;
  keepSeparate: boolean;
  isDirty: boolean;
  expanded: boolean;
}

const AUTO_DETECT: { patterns: RegExp; postingType: 'Debit' | 'Credit'; accountHint: string }[] = [
  { patterns: /Revenue\.Net Sales/i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Revenue\.Gratuity/i, postingType: 'Credit', accountHint: 'Tips' },
  { patterns: /Revenue\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Net Sales\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Tips\./i, postingType: 'Credit', accountHint: 'Tips' },
  { patterns: /Cash Activity\.Cash tips/i, postingType: 'Debit', accountHint: 'Cash' },
  { patterns: /Cash Activity\.Credit/i, postingType: 'Credit', accountHint: 'Tips' },
  { patterns: /Cash Activity\./i, postingType: 'Debit', accountHint: 'Cash' },
  { patterns: /Cash Summary\./i, postingType: 'Debit', accountHint: 'Cash' },
  { patterns: /Payments\.Cash\./i, postingType: 'Debit', accountHint: 'Cash' },
  { patterns: /Payments\.(Credit|Amex|Discover|Mastercard|Visa)\./i, postingType: 'Debit', accountHint: 'Undeposited' },
  { patterns: /Payments\.Gift Card\./i, postingType: 'Debit', accountHint: 'Gift Card' },
  { patterns: /Payments\.House Account\./i, postingType: 'Debit', accountHint: 'Accounts Receivable' },
  { patterns: /Payments\.Other\./i, postingType: 'Debit', accountHint: 'Undeposited' },
  { patterns: /Payments\./i, postingType: 'Debit', accountHint: 'Undeposited' },
  { patterns: /Sales Category\.Food/i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Sales Category\.(Liquor|Beer|Wine|Beverage|Bar)/i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Sales Category\.Merchandise/i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Sales Category\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Tax\./i, postingType: 'Credit', accountHint: 'Sales Tax' },
  { patterns: /Discount\./i, postingType: 'Debit', accountHint: 'Discounts' },
  { patterns: /Service Charge\./i, postingType: 'Credit', accountHint: 'Other Income' },
  { patterns: /Void\./i, postingType: 'Debit', accountHint: 'Discounts' },
  { patterns: /Unpaid Orders\./i, postingType: 'Debit', accountHint: 'Accounts Receivable' },
  { patterns: /Revenue Center\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Service Daypart\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Dining Option\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Service Mode\./i, postingType: 'Credit', accountHint: 'Sales of Product' },
  { patterns: /Deferred\./i, postingType: 'Credit', accountHint: 'Deferred Revenue' },
];

const LINE_ITEM_COLUMN_ROLES = [
  { key: 'productColumn', label: 'Product / Item Name', required: true },
  { key: 'amountColumn', label: 'Amount', required: true },
  { key: 'descriptionColumn', label: 'Description', required: false },
  { key: 'classColumn', label: 'Class', required: false },
  { key: 'taxCodeColumn', label: 'Tax Code', required: false },
] as const;

interface Props {
  jwt: string;
  selectedLocationId: string;
  onLocationChange: (id: string) => void;
  scanData: ScanData | null;
  scanEntries?: ScanEntry[];
  activeScanEntry?: ScanEntry | null;
  activeScanEntryId?: string | null;
  onActiveScanEntryIdChange?: (id: string) => void;
  onTabChange: (tab: TabId) => void;
  onboardingStep?: number;
  onHasMappings?: () => void;
  onSelectedTemplateChange?: (template: Template | null) => void;
  initialTemplate?: Template | null;
  showExcelImportModal?: boolean;
  setShowExcelImportModal?: (open: boolean) => void;
}

function encodeToApi(m: LocalMapping, priority: number): Omit<Mapping, 'id' | 'locationId' | 'createdAt'> {
  return {
    sourceField: m.sourceField,
    targetAccount: m.accountId,
    postingType: m.postingType,
    keepSeparate: m.keepSeparate,
    targetClass: m.classId || undefined,
    targetDescription: m.description || undefined,
    targetMemo: JSON.stringify({
      amountRule: m.amountRule,
      taxCodeId: m.taxCodeId || undefined,
      entityType: m.entityType || undefined,
      entityId: m.entityId || undefined,
    }),
    templateId: m.templateId || undefined,
    priority,
  };
}

function decodeFromApi(m: Mapping): LocalMapping {
  let postingType: 'Debit' | 'Credit' = (m.postingType === 'Debit' || m.postingType === 'Credit') ? m.postingType : 'Credit';
  let keepSeparate = m.keepSeparate ?? false;
  let extra: {
    postingType?: string;
    amountRule?: string;
    keepSeparate?: boolean;
    taxCodeId?: string;
    entityType?: string;
    entityId?: string;
  } = {};

  try {
    if (m.targetMemo) {
      extra = JSON.parse(m.targetMemo) as typeof extra;
      if (m.postingType === undefined && (extra.postingType === 'Debit' || extra.postingType === 'Credit')) {
        postingType = extra.postingType;
      }
      if (m.keepSeparate === undefined && extra.keepSeparate !== undefined) {
        keepSeparate = extra.keepSeparate;
      }
    }
  } catch {
    // ignore
  }

  return {
    localId: m.id,
    remoteId: m.id,
    templateId: m.templateId ?? undefined,
    sourceField: m.sourceField,
    accountId: m.targetAccount,
    postingType,
    description: m.targetDescription ?? '',
    classId: m.targetClass ?? '',
    taxCodeId: extra.taxCodeId ?? '',
    entityType: (extra.entityType as LocalMapping['entityType']) ?? '',
    entityId: extra.entityId ?? '',
    amountRule: extra.amountRule ?? 'Direct Amount',
    keepSeparate,
    isDirty: false,
    expanded: false,
  };
}

function resolveMemoTemplate(template: string, data: Record<string, number> | null): string {
  if (!template || !data) return '';
  return template.replace(/\{(\w+)\}/g, (match, field: string) => {
    const key = Object.keys(data).find(
      (k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase(),
    );
    return key !== undefined ? String(data[key]) : match;
  });
}

function insertAtCursor(
  el: HTMLTextAreaElement | HTMLInputElement | null,
  text: string,
  currentValue: string,
  setValue: (val: string) => void,
): void {
  if (!el) { setValue(currentValue + text); return; }
  const start = el.selectionStart ?? currentValue.length;
  const end = el.selectionEnd ?? currentValue.length;
  const newVal = currentValue.slice(0, start) + text + currentValue.slice(end);
  setValue(newVal);
  requestAnimationFrame(() => {
    el.focus();
    el.setSelectionRange(start + text.length, start + text.length);
  });
}

export default function MappingView({
  jwt,
  selectedLocationId,
  onLocationChange,
  scanData,
  scanEntries,
  activeScanEntry,
  activeScanEntryId,
  onActiveScanEntryIdChange,
  onTabChange,
  onboardingStep = 0,
  onHasMappings,
  onSelectedTemplateChange,
  initialTemplate,
  showExcelImportModal: showExcelImportModalProp,
  setShowExcelImportModal: setShowExcelImportModalProp,
}: Props) {
  const { locations } = useLocations(jwt);
  const {
    accounts,
    classes,
    taxCodes,
    listsLoaded,
    listsLoading,
    listsError,
    syncAllLists,
    searchEntities,
  } = useQBContext();
  const { status: qbStatus } = useQuickBooks(jwt);
  const { showToast } = useToast();

  const [localMappings, setLocalMappings] = useState<LocalMapping[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState<string | null>(null);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [autoMsg, setAutoMsg] = useState<string | null>(null);
  const [memoTemplate, setMemoTemplate] = useState('');
  const [docNumberTemplate, setDocNumberTemplate] = useState('');
  const [memoOpen, setMemoOpen] = useState(true);
  const [fieldsExpanded, setFieldsExpanded] = useState(false);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string>(initialTemplate?.id ?? '');
  const [templatesLoading, setTemplatesLoading] = useState(false);
  const [templatesError, setTemplatesError] = useState<string | null>(null);
  const [billDefaults, setBillDefaults] = useState<Record<string, { value: string; name: string } | null>>({});
  const [billDefaultsDirty, setBillDefaultsDirty] = useState(false);
  const [vendorCreditDefaults, setVendorCreditDefaults] = useState<Record<string, { value: string; name: string } | null>>({});
  const [vendorCreditDefaultsDirty, setVendorCreditDefaultsDirty] = useState(false);
  const [showNewTemplateForm, setShowNewTemplateForm] = useState(false);
  const [newTemplateName, setNewTemplateName] = useState('');
  const [newTemplateType, setNewTemplateType] = useState<keyof typeof TRANSACTION_TYPE_LABELS>('JOURNAL_ENTRY');
  const memoTextareaRef = useRef<HTMLTextAreaElement>(null);
  const docInputRef = useRef<HTMLInputElement>(null);
  const saveTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [importMode, setImportMode] = useState<'replace' | 'merge'>('merge');
  const [importWarning, setImportWarning] = useState<string | null>(null);
  const [showImportConfirm, setShowImportConfirm] = useState(false);
  const [pendingImport, setPendingImport] = useState<ExportTemplate | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [excelSheets, setExcelSheets] = useState<ExcelParseResult['sheets']>([]);
  const [selectedExcelSheetName, setSelectedExcelSheetName] = useState<string>('');
  const [excelColumnMappings, setExcelColumnMappings] = useState<Record<string, string>>({});
  const [localColMap, setLocalColMap] = useState<Record<string, string>>({});
  const [lineItemMappingOpen, setLineItemMappingOpen] = useState(true);
  const [lineItemFieldsOpen, setLineItemFieldsOpen] = useState(false);
  const [localExcelImportModalOpen, setLocalExcelImportModalOpen] = useState(false);
  const [excelLoading, setExcelLoading] = useState(false);
  const [mappingSuggestions, setMappingSuggestions] = useState<MappingSuggestion[]>([]);
  const [suggesting, setSuggesting] = useState(false);
  const [suggestionError, setSuggestionError] = useState<string | null>(null);

  const locId = selectedLocationId || locations[0]?.id || '';
  const showExcelImportModal = showExcelImportModalProp ?? localExcelImportModalOpen;
  const setShowExcelImportModal = setShowExcelImportModalProp ?? setLocalExcelImportModalOpen;

  const accountOptions = useMemo((): SelectOption[] =>
    accounts
      .filter((a) => a.Active)
      .map((a) => ({
        value: a.Id,
        label: a.FullyQualifiedName,
        subtitle: a.AccountSubType,
        group: a.Classification || a.AccountType,
      }))
      .sort((a, b) => (a.group ?? '').localeCompare(b.group ?? '') || a.label.localeCompare(b.label)),
    [accounts],
  );

  const classOptions = useMemo((): SelectOption[] =>
    classes.filter((c) => c.Active).map((c) => ({
      value: c.Id,
      label: c.FullyQualifiedName,
    })),
    [classes],
  );

  const taxCodeOptions = useMemo((): SelectOption[] =>
    taxCodes.filter((t) => t.Active).map((t) => ({
      value: t.Id,
      label: t.Name,
      subtitle: t.Description,
    })),
    [taxCodes],
  );

  const scanFieldOptions = useMemo((): SelectOption[] => {
    if (activeScanEntry) {
      const fieldMap = new Map<string, string>();

      Object.entries(activeScanEntry.header).forEach(([key, value]) => {
        if (!fieldMap.has(key)) {
          fieldMap.set(key, value);
        }
      });

      if (activeScanEntry.lineItems.length > 0) {
        Object.entries(activeScanEntry.lineItems[0]).forEach(([key, value]) => {
          fieldMap.set(key, value);
        });
      }

      return Array.from(fieldMap.entries()).map(([key, value]) => ({
        value: key,
        label: key,
        subtitle: isNaN(Number(value)) || value.trim() === ''
          ? value
          : `$${Number(value).toFixed(2)}`,
      }));
    }

    if (!scanData) return [];

    return Object.entries(scanData).map(([field, amount]) => ({
      value: field,
      label: field,
      subtitle: `$${Number(amount).toFixed(2)}`,
    }));
  }, [activeScanEntry, scanData]);

  const scanFieldChips = useMemo(() => {
    if (!scanData) return [];
    return Object.keys(scanData).map((field) => ({
      original: field,
      normalized: field.toLowerCase().replace(/\s+/g, '_'),
    }));
  }, [scanData]);

  const memoPreview = useMemo(() => resolveMemoTemplate(memoTemplate, scanData), [memoTemplate, scanData]);
  const docPreview = useMemo(() => resolveMemoTemplate(docNumberTemplate, scanData), [docNumberTemplate, scanData]);
  const selectedTemplate = useMemo(() => templates.find((t) => t.id === selectedTemplateId) ?? null, [templates, selectedTemplateId]);
  const isBill = selectedTemplate?.transactionType === 'BILL';
  const isVendorCredit = selectedTemplate?.transactionType === 'VENDOR_CREDIT';
  const isCheque = selectedTemplate?.transactionType === 'CHEQUE';
  const isJE = selectedTemplate?.transactionType === 'JOURNAL_ENTRY';

  const getPreviewLabel = () => {
    switch (selectedTemplate?.transactionType) {
      case 'BILL':
        return 'Bill';
      case 'VENDOR_CREDIT':
        return 'VC';
      case 'CHEQUE':
        return 'Check';
      default:
        return 'JE';
    }
  };

  useEffect(() => {
    setMappingSuggestions([]);
    setSuggestionError(null);
  }, [selectedTemplateId]);
  const hidePostingType = isBill || isVendorCredit;
  const showMappingControls = true;
  const isExcelMode = activeScanEntry?.source === 'excel';
  const activeEntryIndex = scanEntries?.findIndex((entry) => entry.id === activeScanEntryId) ?? -1;
  const totalEntries = scanEntries?.length ?? 0;
  const showEntryNav = totalEntries > 1 && activeScanEntry?.source === 'excel';

  const columnMappingFields = useMemo(() => {
    if (selectedTemplate?.transactionType === 'BILL') {
      return ['vendorRef', 'apAccountRef', 'termsRef', 'dueDate', 'memo', 'docNumber'];
    }
    if (selectedTemplate?.transactionType === 'VENDOR_CREDIT') {
      return ['vendorRef', 'apAccountRef', 'memo', 'docNumber'];
    }
    return ['memo', 'docNumber'];
  }, [selectedTemplate?.transactionType]);

  const lineItemHeaders = useMemo(() => {
    const headers = excelSheets.find((sheet) => sheet.name === selectedExcelSheetName)?.headers;
    if (headers && headers.length > 0) {
      return headers;
    }
    if (activeScanEntry?.lineItems?.[0]) {
      return Object.keys(activeScanEntry.lineItems[0]);
    }
    return [] as string[];
  }, [activeScanEntry, excelSheets, selectedExcelSheetName]);

  useEffect(() => {
    if (!selectedTemplate?.columnMappings) {
      setLocalColMap({});
      return;
    }
    const cm = selectedTemplate.columnMappings as Record<string, unknown>;
    const lineItemKeys = Object.keys(cm).filter((key) => !key.startsWith('_header_'));
    const parsed: Record<string, string> = {};
    for (const key of lineItemKeys) {
      parsed[key] = String(cm[key] ?? '');
    }
    setLocalColMap(parsed);
  }, [selectedTemplate]);

  const getColumnFieldLabel = (field: string) => {
    return BILL_FIELD_LABELS[field] ?? VENDOR_CREDIT_FIELD_LABELS[field] ?? (field === 'memo' ? 'Memo' : field === 'docNumber' ? 'Doc Number' : field);
  };

  useEffect(() => {
    if (selectedTemplate?.transactionType === 'BILL') {
      setBillDefaults((selectedTemplate.defaults as Record<string, { value: string; name: string }> | null) ?? {});
      setBillDefaultsDirty(false);
      setVendorCreditDefaults({});
      setVendorCreditDefaultsDirty(false);
    } else if (selectedTemplate?.transactionType === 'VENDOR_CREDIT') {
      setVendorCreditDefaults((selectedTemplate.defaults as Record<string, { value: string; name: string }> | null) ?? {});
      setVendorCreditDefaultsDirty(false);
      setBillDefaults({});
      setBillDefaultsDirty(false);
    } else {
      setBillDefaults({});
      setBillDefaultsDirty(false);
      setVendorCreditDefaults({});
      setVendorCreditDefaultsDirty(false);
    }
  }, [selectedTemplate]);

  const updateBillDefault = (key: string, value: string) => {
    setBillDefaults((prev) => ({
      ...prev,
      [key]: { value, name: value },
    }));
    setBillDefaultsDirty(true);
  };

  const saveBillDefaults = async () => {
    if (!selectedTemplateId || !jwt) return;
    setTemplatesLoading(true);
    try {
      await api.updateTemplate(jwt, selectedTemplateId, { defaults: billDefaults });
      await loadTemplates();
      setBillDefaultsDirty(false);
      showToast('Bill defaults saved', 'success');
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to save bill defaults', 'error');
    } finally {
      setTemplatesLoading(false);
    }
  };

  const updateVendorCreditDefault = (key: string, value: string) => {
    setVendorCreditDefaults((prev) => ({
      ...prev,
      [key]: { value, name: value },
    }));
    setVendorCreditDefaultsDirty(true);
  };

  const saveVendorCreditDefaults = async () => {
    if (!selectedTemplateId || !jwt) return;
    setTemplatesLoading(true);
    try {
      await api.updateTemplate(jwt, selectedTemplateId, { defaults: vendorCreditDefaults });
      await loadTemplates();
      setVendorCreditDefaultsDirty(false);
      showToast('Vendor Credit defaults saved', 'success');
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to save vendor credit defaults', 'error');
    } finally {
      setTemplatesLoading(false);
    }
  };

  const renderBillHeader = () => (
    <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 space-y-3">
      <div className="text-xs font-semibold text-white">Bill Defaults</div>
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <div className="text-xs text-gray-400 mb-1">{BILL_FIELD_LABELS.vendorRef}</div>
          <input
            type="text"
            value={billDefaults.vendorRef?.value ?? ''}
            onChange={(e) => updateBillDefault('vendorRef', e.target.value)}
            placeholder="e.g. ABC Vendor"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
        <div>
          <div className="text-xs text-gray-400 mb-1">{BILL_FIELD_LABELS.apAccountRef}</div>
          <input
            type="text"
            value={billDefaults.apAccountRef?.value ?? ''}
            onChange={(e) => updateBillDefault('apAccountRef', e.target.value)}
            placeholder="e.g. 33"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
        <div>
          <div className="text-xs text-gray-400 mb-1">{BILL_FIELD_LABELS.termsRef}</div>
          <input
            type="text"
            value={billDefaults.termsRef?.value ?? ''}
            onChange={(e) => updateBillDefault('termsRef', e.target.value)}
            placeholder="e.g. Net 30"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
        <div>
          <div className="text-xs text-gray-400 mb-1">{BILL_FIELD_LABELS.dueDate}</div>
          <input
            type="text"
            value={billDefaults.dueDate?.value ?? ''}
            onChange={(e) => updateBillDefault('dueDate', e.target.value)}
            placeholder="e.g. 30"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
      </div>
      <div className="flex justify-end">
        <button
          type="button"
          disabled={!billDefaultsDirty || templatesLoading}
          onClick={saveBillDefaults}
          className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-40 text-white rounded px-3 py-1.5"
        >
          Save Defaults
        </button>
      </div>
    </div>
  );

  const renderVendorCreditHeader = () => (
    <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 space-y-3">
      <div className="text-xs font-semibold text-white">Vendor Credit Defaults</div>
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <div className="text-xs text-gray-400 mb-1">{VENDOR_CREDIT_FIELD_LABELS.vendorRef}</div>
          <input
            type="text"
            value={vendorCreditDefaults.vendorRef?.value ?? ''}
            onChange={(e) => updateVendorCreditDefault('vendorRef', e.target.value)}
            placeholder="e.g. ABC Vendor"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
        <div>
          <div className="text-xs text-gray-400 mb-1">{VENDOR_CREDIT_FIELD_LABELS.apAccountRef}</div>
          <input
            type="text"
            value={vendorCreditDefaults.apAccountRef?.value ?? ''}
            onChange={(e) => updateVendorCreditDefault('apAccountRef', e.target.value)}
            placeholder="e.g. 33"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
        <div className="sm:col-span-2">
          <div className="text-xs text-gray-400 mb-1">{VENDOR_CREDIT_FIELD_LABELS.docNumber}</div>
          <input
            type="text"
            value={vendorCreditDefaults.docNumber?.value ?? ''}
            onChange={(e) => updateVendorCreditDefault('docNumber', e.target.value)}
            placeholder="e.g. VC-001"
            className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
          />
        </div>
      </div>
      <div className="flex justify-end">
        <button
          type="button"
          disabled={!vendorCreditDefaultsDirty || templatesLoading}
          onClick={saveVendorCreditDefaults}
          className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-40 text-white rounded px-3 py-1.5"
        >
          Save Defaults
        </button>
      </div>
    </div>
  );

  const selectedTemplateHasMappings = useMemo(
    () => selectedTemplateId !== '' && localMappings.some((mapping) => mapping.templateId === selectedTemplateId),
    [localMappings, selectedTemplateId],
  );

  useEffect(() => {
    onSelectedTemplateChange?.(selectedTemplate);
  }, [selectedTemplate, onSelectedTemplateChange]);

  const loadTemplates = useCallback(async () => {
    if (!locId || !jwt) return;
    setTemplatesLoading(true);
    setTemplatesError(null);
    try {
      const data = await api.getTemplates(jwt, locId);
      setTemplates(data);
      setSelectedTemplateId((current) => {
        if (current && data.some((t) => t.id === current)) return current;
        return data[0]?.id ?? '';
      });
    } catch (err) {
      setTemplatesError(err instanceof Error ? err.message : 'Failed to load templates');
    } finally {
      setTemplatesLoading(false);
    }
  }, [jwt, locId]);

  useEffect(() => { void loadTemplates(); }, [loadTemplates]);

  useEffect(() => {
    if (!selectedTemplate) {
      setMemoTemplate('');
      setDocNumberTemplate('');
      return;
    }
    setMemoTemplate(selectedTemplate.memoTemplate ?? '');
    setDocNumberTemplate(selectedTemplate.docNumberTemplate ?? '');
  }, [selectedTemplate]);

  const debouncedSaveTemplates = useCallback((memo: string, doc: string) => {
    if (!selectedTemplateId || !jwt) return;
    if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    saveTimerRef.current = setTimeout(() => {
      api.updateTemplate(jwt, selectedTemplateId, { memoTemplate: memo || undefined, docNumberTemplate: doc || undefined })
        .catch(() => { /* silent — will retry on next change */ });
    }, 1500);
  }, [selectedTemplateId, jwt]);

  useEffect(() => {
    if (!listsLoaded && !listsLoading && !listsError) void syncAllLists();
  }, [listsLoaded, listsLoading, listsError, syncAllLists]);

  const loadMappings = useCallback(async () => {
    if (!locId || !selectedTemplateId) {
      setLocalMappings([]);
      return;
    }
    setLoading(true);
    try {
      const data = await api.getMappings(jwt, locId);
      const filtered = data.filter((mapping) => mapping.templateId === selectedTemplateId);
      setLocalMappings(filtered.map(decodeFromApi));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load mappings');
    } finally {
      setLoading(false);
    }
  }, [jwt, locId, selectedTemplateId]);

  useEffect(() => {
    if (!locId || !selectedTemplateId) {
      setLocalMappings([]);
      return;
    }
    void loadMappings();
  }, [loadMappings, locId, selectedTemplateId]);

  const handleTemplateChange = (templateId: string) => {
    if (localMappings.some((mapping) => mapping.isDirty)) {
      if (!window.confirm('You have unsaved mapping changes. Switch templates anyway?')) {
        return;
      }
    }
    setSelectedTemplateId(templateId);
  };

  const resetNewTemplateForm = () => {
    setShowNewTemplateForm(false);
    setNewTemplateName('');
    setNewTemplateType('JOURNAL_ENTRY');
  };

  const openNewTemplateForm = () => {
    setNewTemplateName('');
    setNewTemplateType('JOURNAL_ENTRY');
    setShowNewTemplateForm(true);
  };

  const handleSubmitNewTemplate = async () => {
    if (!locId || !jwt || !newTemplateName.trim()) return;
    setTemplatesLoading(true);
    try {
      const created = await api.createTemplate(jwt, locId, {
        name: newTemplateName.trim(),
        transactionType: newTemplateType,
      });
      setTemplates((prev) => [...prev, created]);
      setSelectedTemplateId(created.id);
      await loadTemplates();
      showToast('Template created', 'success');
      resetNewTemplateForm();
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to create template', 'error');
    } finally {
      setTemplatesLoading(false);
    }
  };

  const handleNewTemplateKeyDown = async (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      if (newTemplateName.trim()) {
        await handleSubmitNewTemplate();
      }
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      resetNewTemplateForm();
    }
  };


  const handleDeleteTemplate = async () => {
    if (!selectedTemplateId || templates.length <= 1) return;
    if (!window.confirm('Delete this template and ALL its mappings? This cannot be undone.')) return;

    setTemplatesLoading(true);
    try {
      await api.deleteTemplate(jwt, selectedTemplateId);
      const remaining = templates.filter((t) => t.id !== selectedTemplateId);
      setTemplates(remaining);
      setSelectedTemplateId(remaining[0]?.id ?? '');
      showToast('Template deleted', 'success');
      if (remaining[0]?.id) {
        void loadMappings();
      } else {
        setLocalMappings([]);
      }
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to delete template', 'error');
    } finally {
      setTemplatesLoading(false);
    }
  };

  const hasReportedMappings = useRef(false);
  useEffect(() => {
    if (localMappings.length > 0 && !hasReportedMappings.current) {
      hasReportedMappings.current = true;
      onHasMappings?.();
    }
  }, [localMappings.length, onHasMappings]);

  useEffect(() => {
    debouncedSaveTemplates(memoTemplate, docNumberTemplate);
    return () => {
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
    };
  }, [memoTemplate, docNumberTemplate, debouncedSaveTemplates]);

  useEffect(() => {
    if (!selectedLocationId && locations[0]) onLocationChange(locations[0].id);
  }, [locations, selectedLocationId, onLocationChange]);

  const updateMapping = (localId: string, patch: Partial<LocalMapping>) => {
    setLocalMappings((prev) => prev.map((mapping) => (
      mapping.localId === localId ? { ...mapping, ...patch, isDirty: true } : mapping
    )));
  };

  const toggleExpand = (localId: string) => {
    setLocalMappings((prev) => prev.map((mapping) => (
      mapping.localId === localId ? { ...mapping, expanded: !mapping.expanded } : mapping
    )));
  };

  const addMapping = () => {
    if (!selectedTemplateId) return;
    const newMapping: LocalMapping = {
      localId: `new-${Date.now()}`,
      remoteId: undefined,
      templateId: selectedTemplateId || undefined,
      sourceField: '',
      accountId: '',
      postingType: selectedTemplate?.transactionType === 'VENDOR_CREDIT' ? 'Debit' : 'Credit',
      description: '',
      classId: '',
      taxCodeId: '',
      entityType: '',
      entityId: '',
      amountRule: 'Direct Amount',
      keepSeparate: false,
      isDirty: true,
      expanded: true,
    };
    setLocalMappings((prev) => [...prev, newMapping]);
  };

  const saveMapping = async (mapping: LocalMapping, priority: number) => {
    if (!mapping.sourceField || !mapping.accountId) {
      setError('Source field and QB Account are required');
      return;
    }
    setSaving(mapping.localId);
    setError(null);
    try {
      const payload = encodeToApi(mapping, priority);
      if (mapping.remoteId) {
        await api.updateMapping(jwt, mapping.remoteId, payload);
      } else {
        const created = await api.createMapping(jwt, locId, payload);
        setLocalMappings((prev) => prev.map((item) => (
          item.localId === mapping.localId
            ? { ...item, remoteId: created.id, localId: created.id, isDirty: false }
            : item
        )));
        return;
      }
      setLocalMappings((prev) => prev.map((item) => (
        item.localId === mapping.localId ? { ...item, isDirty: false } : item
      )));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save');
    } finally {
      setSaving(null);
    }
  };

  const deleteMapping = async (mapping: LocalMapping) => {
    if (mapping.remoteId && !window.confirm('Delete this mapping?')) return;
    if (!mapping.remoteId) {
      setLocalMappings((prev) => prev.filter((item) => item.localId !== mapping.localId));
      return;
    }
    setDeleting(mapping.localId);
    try {
      await api.deleteMapping(jwt, mapping.remoteId);
      setLocalMappings((prev) => prev.filter((item) => item.localId !== mapping.localId));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete');
    } finally {
      setDeleting(null);
    }
  };

  const autoDetect = () => {
    if (!selectedTemplateId) {
      setAutoMsg('Select a template first before using Auto-Detect.');
      return;
    }
    if (!scanData || accounts.length === 0) {
      setAutoMsg('No scan data or QB accounts loaded');
      return;
    }

    let applied = 0;
    const newMappings: LocalMapping[] = [];
    const scanFields = Object.keys(scanData);

    scanFields.forEach((field) => {
      if (localMappings.some((mapping) => mapping.sourceField === field)) return;
      const rule = AUTO_DETECT.find((rule) => rule.patterns.test(field));
      if (!rule) return;
      const expectedTypesForPostingType = (postingType: 'Debit' | 'Credit'): string[] =>
        postingType === 'Debit'
          ? ['Asset', 'Expense']
          : ['Liability', 'Equity', 'Income'];

      const matchedAccount = accounts.find(
        (account) =>
          account.Active &&
          account.FullyQualifiedName.toLowerCase().includes(rule.accountHint.toLowerCase()) &&
          expectedTypesForPostingType(rule.postingType).includes(account.AccountType),
      );
      if (!matchedAccount) return;
      newMappings.push({
        localId: `auto-${Date.now()}-${field}`,
        remoteId: undefined,
        sourceField: field,
        accountId: matchedAccount.Id,
        postingType: rule.postingType,
        description: field,
        classId: '',
        taxCodeId: '',
        entityType: '' as LocalMapping['entityType'],
        entityId: '',
        amountRule: 'Direct Amount',
        keepSeparate: false,
        isDirty: true,
        expanded: false,
      });
      applied += 1;
    });

    setLocalMappings((prev) => [...prev, ...newMappings]);
    setAutoMsg(
      applied > 0
        ? `✅ ${applied} mapping${applied !== 1 ? 's' : ''} auto-detected`
        : 'No new mappings detected',
    );
    setTimeout(() => setAutoMsg(null), 4000);
  };

  const suggestMappings = async () => {
    if (!selectedTemplateId) {
      setSuggestionError('Select a template first before using AI Suggest.');
      return;
    }
    if (accounts.length === 0) {
      setSuggestionError('No QuickBooks accounts are loaded. Refresh QB lists first.');
      return;
    }

    const sourceFields = scanFieldOptions.map((option) => option.value).filter((value) =>
      !localMappings.some((mapping) => mapping.sourceField === value),
    );
    if (sourceFields.length === 0) {
      setSuggestionError('No unmapped scan fields are available for suggestion.');
      return;
    }

    setSuggesting(true);
    setSuggestionError(null);
    setMappingSuggestions([]);

    try {
      const result = await api.suggestMappings(jwt, locId, sourceFields, selectedTemplate?.transactionType);
      const suggestions = result.suggestions ?? [];
      if (suggestions.length === 0) {
        setSuggestionError('AI did not return any mapping suggestions.');
        return;
      }
      setMappingSuggestions(suggestions);
      setAutoMsg(`🤖 ${suggestions.length} AI suggestion${suggestions.length !== 1 ? 's' : ''} ready`);
      setTimeout(() => setAutoMsg(null), 4000);
    } catch (err: any) {
      const msg = err?.message || 'Failed to fetch AI suggestions';
      if (msg.includes('rate limited') || msg.includes('429')) {
        setSuggestionError('⚠️ AI is busy right now. Please wait about 30 seconds, then try again.');
      } else {
        setSuggestionError(msg);
      }
    } finally {
      setSuggesting(false);
    }
  };

  const applySuggestions = () => {
    if (mappingSuggestions.length === 0) return;

    const existingFields = new Set(localMappings.map((m) => m.sourceField));
    const fresh = mappingSuggestions.filter((s) => !existingFields.has(s.sourceField));
    const skipped = mappingSuggestions.length - fresh.length;

    if (fresh.length === 0) {
      setAutoMsg(`All ${skipped} suggestion${skipped !== 1 ? 's' : ''} already mapped`);
      setMappingSuggestions([]);
      setTimeout(() => setAutoMsg(null), 4000);
      return;
    }

    const newMappings: LocalMapping[] = fresh.map((suggestion) => ({
      localId: `ai-${Date.now()}-${suggestion.sourceField}`,
      remoteId: undefined,
      sourceField: suggestion.sourceField,
      accountId: suggestion.accountId || '',
      postingType: suggestion.postingType,
      description: suggestion.sourceField,
      classId: '',
      taxCodeId: '',
      entityType: '' as LocalMapping['entityType'],
      entityId: '',
      amountRule: 'Direct Amount',
      keepSeparate: false,
      isDirty: true,
      expanded: false,
    }));

    setLocalMappings((prev) => [...prev, ...newMappings]);
    setMappingSuggestions([]);
    const msg = skipped > 0
      ? `✅ ${fresh.length} applied, ${skipped} already mapped`
      : `✅ ${fresh.length} AI suggestion${fresh.length !== 1 ? 's' : ''} applied`;
    setAutoMsg(msg);
    setTimeout(() => setAutoMsg(null), 4000);
  };

  const applyTemplate = (templateName: string) => {
    if (!selectedTemplateId) {
      setAutoMsg('Select a template first before applying a preset.');
      return;
    }
    const matchingTemplates: Record<string, { field: string; postingType: 'Debit' | 'Credit'; accountHint: string }[]> = {
      'Standard Daily': [
        { field: 'Revenue.Net sales', postingType: 'Credit', accountHint: 'Sales of Product' },
        { field: 'Revenue.Tax amount', postingType: 'Credit', accountHint: 'Sales Tax' },
        { field: 'Tips.Total tips', postingType: 'Credit', accountHint: 'Tips' },
        { field: 'Payments.Credit/debit.Total', postingType: 'Debit', accountHint: 'Undeposited' },
        { field: 'Payments.Cash.Total', postingType: 'Debit', accountHint: 'Cash' },
      ],
      'Full Service': [
        { field: 'Revenue.Net sales', postingType: 'Credit', accountHint: 'Sales of Product' },
        { field: 'Revenue.Gratuity', postingType: 'Credit', accountHint: 'Tips' },
        { field: 'Revenue.Tax amount', postingType: 'Credit', accountHint: 'Sales Tax' },
        { field: 'Tips.Credit/non-cash tips', postingType: 'Credit', accountHint: 'Tips' },
        { field: 'Tips.Cash tips', postingType: 'Credit', accountHint: 'Tips' },
        { field: 'Discount.Total discounts.Amount', postingType: 'Debit', accountHint: 'Discounts' },
        { field: 'Payments.Credit/debit.Total', postingType: 'Debit', accountHint: 'Undeposited' },
        { field: 'Payments.Cash.Total', postingType: 'Debit', accountHint: 'Cash' },
        { field: 'Payments.Gift Card.Total', postingType: 'Debit', accountHint: 'Gift Card' },
      ],
      'Quick Service': [
        { field: 'Revenue.Net sales', postingType: 'Credit', accountHint: 'Sales of Product' },
        { field: 'Revenue.Tax amount', postingType: 'Credit', accountHint: 'Sales Tax' },
        { field: 'Payments.Credit/debit.Total', postingType: 'Debit', accountHint: 'Undeposited' },
        { field: 'Payments.Cash.Total', postingType: 'Debit', accountHint: 'Cash' },
      ],
    };

    const tpl = matchingTemplates[templateName];
    if (!tpl || accounts.length === 0) return;

    const newMappings: LocalMapping[] = tpl
      .filter((item) => !localMappings.some((mapping) => mapping.sourceField === item.field))
      .map((item) => {
        const matchedAccount = accounts.find(
          (account) => account.Active && account.FullyQualifiedName.toLowerCase().includes(item.accountHint.toLowerCase()),
        );
        return {
          localId: `tpl-${Date.now()}-${item.field}`,
          remoteId: undefined,
          templateId: selectedTemplateId || undefined,
          sourceField: item.field,
          accountId: matchedAccount?.Id ?? '',
          postingType: item.postingType,
          description: item.field,
          classId: '',
          taxCodeId: '',
          entityType: '' as LocalMapping['entityType'],
          entityId: '',
          amountRule: 'Direct Amount',
          keepSeparate: false,
          isDirty: true,
          expanded: false,
        };
      });

    setLocalMappings((prev) => [...prev, ...newMappings]);
    setAutoMsg(`✅ Template "${templateName}" applied — ${newMappings.length} rows added`);
    setTimeout(() => setAutoMsg(null), 4000);
  };

  const handleExport = useCallback(async () => {
    if (!locId || !jwt) return;
    try {
      const [mappings, rules] = await Promise.all([
        api.getMappings(jwt, locId),
        api.getRules(jwt, locId),
      ]);
      const loc = locations.find((l) => l.id === locId);
      const exportData: ExportTemplate = {
        version: 1,
        exportedAt: new Date().toISOString(),
        sourceLocationName: loc?.name ?? 'Unknown',
        sourceRealmId: qbStatus?.realmId ?? '',
        memoTemplate,
        docNumberTemplate,
        mappings: mappings.map((mapping) => ({
          sourceField: mapping.sourceField,
          targetAccount: mapping.targetAccount,
          postingType: mapping.postingType ?? 'Credit',
          keepSeparate: mapping.keepSeparate ?? false,
          targetClass: mapping.targetClass ?? undefined,
          targetName: mapping.targetName ?? undefined,
          targetDescription: mapping.targetDescription ?? undefined,
          targetMemo: mapping.targetMemo ?? undefined,
          priority: mapping.priority,
        })),
        rules: rules.map((rule) => ({
          name: rule.name,
          ruleType: rule.ruleType,
          config: rule.config as Record<string, unknown>,
          isActive: rule.isActive,
        })),
      };
      const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `nest-template-${(loc?.name ?? 'location').replace(/[^a-z0-9]/gi, '-').toLowerCase()}-${new Date().toISOString().slice(0, 10)}.json`;
      document.body.appendChild(anchor);
      anchor.click();
      document.body.removeChild(anchor);
      URL.revokeObjectURL(url);
      showToast(`Exported ${mappings.length} mappings + ${rules.length} rules`, 'success');
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Export failed', 'error');
    }
  }, [jwt, locId, locations, memoTemplate, docNumberTemplate, qbStatus, showToast]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target?.result as string) as ExportTemplate;
        if (!data.version || !data.mappings || !data.rules) {
          showToast('Invalid template file format', 'error');
          return;
        }
        if (data.version !== 1) {
          showToast('Unsupported template version', 'error');
          return;
        }
        const currentRealmId = qbStatus?.realmId;
        if (data.sourceRealmId && currentRealmId && data.sourceRealmId !== currentRealmId) {
          setImportWarning('This template was exported from a different QuickBooks company. Some account references may not match. Verify mappings after import.');
        } else {
          setImportWarning(null);
        }
        setPendingImport(data);
        setShowImportConfirm(true);
      } catch {
        showToast('Failed to read template file', 'error');
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  }, [qbStatus, showToast]);

  const handleImportConfirm = useCallback(async () => {
    if (!pendingImport || !locId || !jwt) return;
    try {
      const result = await api.importTemplate(jwt, locId, {
        mappings: pendingImport.mappings,
        rules: pendingImport.rules,
        memoTemplate: pendingImport.memoTemplate,
        docNumberTemplate: pendingImport.docNumberTemplate,
        mode: importMode,
      });
      showToast(`Imported ${result.createdMappings} mappings + ${result.createdRules} rules${result.templatesUpdated ? ' + templates' : ''}`, 'success');
      void loadMappings();
      const loc = locations.find((l) => l.id === locId);
      if (loc) {
        setMemoTemplate(pendingImport.memoTemplate ?? loc.memoTemplate ?? '');
        setDocNumberTemplate(pendingImport.docNumberTemplate ?? loc.docNumberTemplate ?? '');
      }
      setShowImportConfirm(false);
      setPendingImport(null);
      setImportWarning(null);
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Import failed', 'error');
    }
  }, [pendingImport, locId, jwt, importMode, showToast, loadMappings, locations]);

  const saveExcelColumnMappings = useCallback(async () => {
    if (!selectedTemplateId || !jwt) return;
    try {
      await api.updateTemplate(jwt, selectedTemplateId, {
        columnMappings: excelColumnMappings,
      });
      await loadTemplates();
      showToast('Excel column mappings saved', 'success');
      setShowExcelImportModal(false);
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to save Excel mappings', 'error');
    }
  }, [excelColumnMappings, jwt, selectedTemplateId, loadTemplates, showToast]);

  const saveLineItemColumnMappings = useCallback(async () => {
    if (!selectedTemplateId || !jwt || !selectedTemplate) return;
    try {
      const merged = {
        ...(selectedTemplate.columnMappings ?? {}),
        ...localColMap,
      };
      await api.updateTemplate(jwt, selectedTemplateId, {
        columnMappings: merged,
      });
      await loadTemplates();
      showToast('Line item column roles saved', 'success');
    } catch (err) {
      showToast(err instanceof Error ? err.message : 'Failed to save line item mappings', 'error');
    }
  }, [jwt, selectedTemplateId, selectedTemplate, localColMap, loadTemplates, showToast]);

  const getAmountForField = (field: string): number => {
    if (activeScanEntry?.lineItems?.[0]) {
      const raw = activeScanEntry.lineItems[0][field];
      if (raw !== undefined && raw !== '') {
        const parsed = Number(raw);
        if (!Number.isNaN(parsed)) return Math.abs(parsed);
      }
    }
    if (activeScanEntry?.header) {
      const raw = activeScanEntry.header[field];
      if (raw !== undefined && raw !== '') {
        const parsed = Number(raw);
        if (!Number.isNaN(parsed)) return Math.abs(parsed);
      }
    }
    return Math.abs(scanData?.[field] ?? 0);
  };

  const totalDebits = localMappings
    .filter((mapping) => mapping.postingType === 'Debit')
    .reduce((sum, mapping) => sum + getAmountForField(mapping.sourceField), 0);
  const totalCredits = localMappings
    .filter((mapping) => mapping.postingType === 'Credit')
    .reduce((sum, mapping) => sum + getAmountForField(mapping.sourceField), 0);
  const diff = totalCredits - totalDebits;
  const isBalanced = Math.abs(diff) < 0.01;

  const buildEntityOptions = useCallback((query: string): SelectOption[] => {
    return searchEntities(query || '').map((entity) => ({
      value: `${entity.type}:${entity.id}`,
      label: entity.displayName,
      subtitle: entity.type,
    }));
  }, [searchEntities]);

  return (
    <div className="p-3 space-y-3">
      {showEntryNav && (
        <div className="flex items-center justify-between px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg mb-3">
          <button
            type="button"
            onClick={() => {
              const prev = activeEntryIndex - 1;
              if (prev >= 0 && scanEntries) onActiveScanEntryIdChange?.(scanEntries[prev].id);
            }}
            disabled={activeEntryIndex <= 0}
            className="px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
          >
            ← Prev
          </button>
          <span className="text-xs text-gray-300 font-medium">
            Entry {activeEntryIndex + 1} of {totalEntries}
          </span>
          <button
            type="button"
            onClick={() => {
              const next = activeEntryIndex + 1;
              if (next < totalEntries && scanEntries) onActiveScanEntryIdChange?.(scanEntries[next].id);
            }}
            disabled={activeEntryIndex >= totalEntries - 1}
            className="px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
          >
            Next →
          </button>
        </div>
      )}
      <MappingFilters
        locId={locId}
        locations={locations}
        onLocationChange={onLocationChange}
        onExport={handleExport}
        onImport={() => fileInputRef.current?.click()}
        onAutoDetect={autoDetect}
        onAISuggest={suggestMappings}
        onApplyTemplate={applyTemplate}
        onSyncLists={() => void syncAllLists()}
        listsLoading={listsLoading}
        accountsLoaded={accounts.length > 0}
        showImportButton={showMappingControls}
        disableAutoDetect={isExcelMode}
        disablePresets={isExcelMode}
      />

      <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 space-y-3">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="min-w-0 flex-1">
            <label className="block text-xs text-gray-400 mb-1">Template</label>
            <select
              value={selectedTemplateId}
              onChange={(e) => handleTemplateChange(e.target.value)}
              disabled={templatesLoading}
              className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
            >
              {templates.map((template) => (
                <option key={template.id} value={template.id}>
                  {template.name} ({TRANSACTION_TYPE_LABELS[template.transactionType] ?? template.transactionType})
                </option>
              ))}
            </select>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {!showNewTemplateForm && (
              <button
                type="button"
                onClick={openNewTemplateForm}
                className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white rounded px-3 py-1.5"
              >
                + New
              </button>
            )}
            {selectedTemplate && !showNewTemplateForm && (
              <div className="text-xs text-gray-400 px-3 py-1.5 rounded border border-gray-700">
                {TRANSACTION_TYPE_LABELS[selectedTemplate.transactionType] ?? selectedTemplate.transactionType}
              </div>
            )}
            {templates.length > 1 && (
              <button
                type="button"
                onClick={handleDeleteTemplate}
                disabled={templatesLoading}
                className="text-xs bg-red-800 hover:bg-red-700 text-white rounded px-3 py-1.5"
              >
                ✕ Delete
              </button>
            )}
          </div>
        </div>
        {selectedTemplateHasMappings && (
          <div className="text-xs text-orange-300">Changing type may affect existing mappings.</div>
        )}
        {showNewTemplateForm && (
          <div className="space-y-2">
            <div className="grid gap-2 sm:grid-cols-[1.6fr_1fr]">
              <input
                type="text"
                autoFocus
                placeholder="Template name"
                value={newTemplateName}
                onChange={(e) => setNewTemplateName(e.target.value)}
                onKeyDown={handleNewTemplateKeyDown}
                className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
              />
              <select
                value={newTemplateType}
                onChange={(e) => setNewTemplateType(e.target.value as keyof typeof TRANSACTION_TYPE_LABELS)}
                className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
              >
                {TRANSACTION_TYPES.map((type) => (
                  <option key={type} value={type}>
                    {TRANSACTION_TYPE_LABELS[type]}
                  </option>
                ))}
              </select>
            </div>
            <div className="flex flex-wrap gap-2">
              <button
                type="button"
                disabled={!newTemplateName.trim() || templatesLoading}
                onClick={handleSubmitNewTemplate}
                className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded px-3 py-1.5"
              >
                Create
              </button>
              <button
                type="button"
                onClick={resetNewTemplateForm}
                className="text-xs bg-gray-700 hover:bg-gray-600 text-white rounded px-3 py-1.5"
              >
                Cancel
              </button>
            </div>
          </div>
        )}
        {templatesError ? (
          <div className="text-xs text-red-400">{templatesError}</div>
        ) : null}
        {templatesLoading ? (
          <div className="text-xs text-gray-400">Loading templates…</div>
        ) : null}
      </div>

      {!templatesLoading && templates.length === 0 && (
        <div className="rounded-lg border border-gray-700 bg-gray-900 p-4 text-center">
          <p className="text-sm text-gray-300 mb-3">No templates yet. Create your first template to start mapping.</p>
          <button
            type="button"
            onClick={openNewTemplateForm}
            className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white rounded px-3 py-1.5"
          >
            Create Default Template
          </button>
        </div>
      )}

      <input
        ref={fileInputRef}
        type="file"
        accept=".json"
        aria-label="Import template JSON file"
        className="hidden"
        onChange={handleFileSelect}
      />

      {showExcelImportModal && excelSheets.length > 0 && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-gray-900 border border-gray-700 rounded-lg p-4 w-full max-w-3xl space-y-4">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
              <div>
                <h3 className="text-sm font-semibold text-white">Excel Column Mappings</h3>
                <p className="text-xs text-gray-400 max-w-2xl">
                  Map the imported spreadsheet columns to fields used by the selected template.
                </p>
                {selectedTemplate?.columnMappings && Object.keys(selectedTemplate.columnMappings).length > 0 && (
                  <p className="text-sm text-gray-500 mt-2">
                    This template has an existing column mapping. Upload a new file to reconfigure it.
                  </p>
                )}
              </div>
              <button
                type="button"
                onClick={() => setShowExcelImportModal(false)}
                className="text-xs bg-gray-800 hover:bg-gray-700 text-gray-300 rounded px-3 py-1.5"
              >
                Close
              </button>
            </div>

            {excelSheets.length > 1 && (
              <div className="space-y-2">
                <div className="text-xs text-gray-400">Worksheet</div>
                <select
                  value={selectedExcelSheetName}
                  onChange={(e) => setSelectedExcelSheetName(e.target.value)}
                  className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
                >
                  {excelSheets.map((sheet) => (
                    <option key={sheet.name} value={sheet.name}>{sheet.name}</option>
                  ))}
                </select>
              </div>
            )}

            <div className="grid gap-3 md:grid-cols-2">
              {columnMappingFields.map((field) => (
                <div key={field}>
                  <div className="text-xs text-gray-400 mb-1">{getColumnFieldLabel(field)}</div>
                  <select
                    value={excelColumnMappings[field] ?? ''}
                    onChange={(e) => setExcelColumnMappings((prev) => ({ ...prev, [field]: e.target.value }))}
                    className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
                  >
                    <option value="">Select column</option>
                    {(excelSheets.find((sheet) => sheet.name === selectedExcelSheetName)?.headers ?? []).map((header) => (
                      <option key={header} value={header}>{header}</option>
                    ))}
                  </select>
                </div>
              ))}
            </div>

            <div>
              <div className="text-xs text-gray-400 mb-2">Preview</div>
              <div className="overflow-x-auto border border-gray-700 rounded-lg bg-gray-950">
                <table className="min-w-full text-left text-xs text-gray-200">
                  <thead>
                    <tr className="border-b border-gray-700 bg-gray-900 text-gray-300">
                      {(excelSheets.find((sheet) => sheet.name === selectedExcelSheetName)?.headers ?? []).map((header) => (
                        <th key={header} className="px-2 py-2">{header}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {(excelSheets.find((sheet) => sheet.name === selectedExcelSheetName)?.rows ?? []).map((row, rowIndex) => (
                      <tr key={rowIndex} className="odd:bg-gray-950 even:bg-gray-900">
                        {(excelSheets.find((sheet) => sheet.name === selectedExcelSheetName)?.headers ?? []).map((header) => (
                          <td key={header} className="px-2 py-2 text-gray-300 truncate max-w-[10rem]">{row[header]}</td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            <div className="flex flex-wrap gap-2 justify-end">
              <button
                type="button"
                onClick={() => setShowExcelImportModal(false)}
                className="text-xs bg-gray-800 hover:bg-gray-700 text-gray-300 rounded px-3 py-1.5"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => void saveExcelColumnMappings()}
                disabled={excelLoading}
                className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded px-3 py-1.5"
              >
                {excelLoading ? 'Saving…' : 'Save Mappings'}
              </button>
            </div>
          </div>
        </div>
      )}

      {showImportConfirm && pendingImport && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-gray-900 border border-gray-700 rounded-lg p-4 w-80 space-y-3">
            <h3 className="text-sm font-semibold text-white">Import Template</h3>
            <p className="text-xs text-gray-400">
              Import from: <span className="text-gray-200">{pendingImport.sourceLocationName || 'Unknown'}</span>
            </p>
            <div className="text-xs text-gray-400 space-y-1">
              <p>{pendingImport.mappings.length} mappings, {pendingImport.rules.length} rules</p>
              <p>Templates: {(pendingImport.memoTemplate || pendingImport.docNumberTemplate) ? 'Yes' : 'No'}</p>
            </div>
            {importWarning && (
              <div className="bg-orange-900/30 border border-orange-700 text-orange-300 text-xs rounded px-3 py-2">
                ⚠️ {importWarning}
              </div>
            )}
            <div className="space-y-2">
              <div className="text-xs text-gray-400">Mode:</div>
              <div className="flex gap-2">
                <label className="flex items-center gap-1.5 text-xs text-gray-300 cursor-pointer">
                  <input
                    type="radio"
                    name="importMode"
                    checked={importMode === 'merge'}
                    onChange={() => setImportMode('merge')}
                    className="accent-cyan-500"
                  />
                  Merge (add to existing)
                </label>
                <label className="flex items-center gap-1.5 text-xs text-gray-300 cursor-pointer">
                  <input
                    type="radio"
                    name="importMode"
                    checked={importMode === 'replace'}
                    onChange={() => setImportMode('replace')}
                    className="accent-red-500"
                  />
                  Replace all
                </label>
              </div>
            </div>
            <div className="flex gap-2 pt-1">
              <button
                type="button"
                onClick={() => {
                  setShowImportConfirm(false);
                  setPendingImport(null);
                  setImportWarning(null);
                }}
                className="flex-1 text-xs bg-gray-700 hover:bg-gray-600 text-gray-300 py-2 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => void handleImportConfirm()}
                className="flex-1 text-xs bg-cyan-700 hover:bg-cyan-600 text-white py-2 rounded-lg transition-colors"
              >
                Import
              </button>
            </div>
          </div>
        </div>
      )}

      {autoMsg && (
        <div className="bg-green-900/30 border border-green-700 text-green-300 text-xs rounded-lg px-3 py-2">
          {autoMsg}
        </div>
      )}
      {error && <ErrorCard message={error} onDismiss={() => setError(null)} />}
      {suggestionError && (
        <div className="bg-red-900/30 border border-red-700 text-red-300 text-xs rounded-lg px-3 py-2">
          {suggestionError}
        </div>
      )}
      {mappingSuggestions.length > 0 && (
        <div className="bg-gray-900 border border-gray-700 rounded-lg p-3 space-y-3">
          <div className="flex items-center justify-between gap-3">
            <div>
              <div className="text-xs font-semibold text-white">AI Mapping Suggestions</div>
              <div className="text-xs text-gray-400">Review the recommendations below before applying them.</div>
            </div>
            <button
              type="button"
              onClick={applySuggestions}
              disabled={suggesting}
              className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:opacity-40 disabled:cursor-not-allowed text-white rounded px-3 py-1.5"
            >
              Apply Suggestions
            </button>
          </div>
          <div className="grid gap-2">
            {mappingSuggestions.map((suggestion) => (
              <div key={suggestion.sourceField} className="border border-gray-700 rounded-lg p-3 bg-gray-800">
                <div className="flex items-center justify-between gap-2">
                  <div className="text-sm font-medium text-white">{suggestion.sourceField}</div>
                  <span className="text-xs text-gray-400">{suggestion.postingType}</span>
                </div>
                <div className="text-xs text-gray-400 mt-1">Account: {suggestion.accountName || suggestion.accountHint}</div>
                <div className="text-xs text-gray-500 mt-1">{suggestion.reason}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
        <button
          type="button"
          onClick={() => setMemoOpen((current) => !current)}
          className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-700/50 transition-colors"
        >
          <span className="text-xs font-semibold text-gray-300">
            📝 Memo Template <span className="text-gray-600 font-normal">(auto-fills Private Note on journal entry)</span>
          </span>
          <span className="text-gray-500 text-xs">{memoOpen ? '▲' : '▼'}</span>
        </button>
        {memoOpen && (
          <div className="px-3 pb-3 space-y-3 border-t border-gray-700/60 pt-3">
            <p className="text-xs text-gray-500">
              Use <code className="text-cyan-400 bg-gray-900 px-1 rounded">{'{field_name}'}</code> placeholders to insert scan values. Click a chip to insert at cursor.
            </p>

            <div>
              <div className="text-xs text-gray-500 mb-1">Private Note / Memo</div>
              <textarea
                ref={memoTextareaRef}
                className="w-full bg-gray-900 border border-gray-700 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none resize-none"
                rows={2}
                value={memoTemplate}
                onChange={(e) => setMemoTemplate(e.target.value)}
                placeholder="e.g. Daily Sales — {location} — {report_date}"
              />
              {memoPreview && (
                <p className="text-xs text-gray-600 italic mt-1 truncate">Preview: {memoPreview}</p>
              )}
            </div>

            <div>
              <div className="text-xs text-gray-500 mb-1">
                Doc Number <span className="text-gray-600">(leave blank for QB auto-generate)</span>
              </div>
              <input
                ref={docInputRef}
                className="w-full bg-gray-900 border border-gray-700 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
                value={docNumberTemplate}
                onChange={(e) => setDocNumberTemplate(e.target.value)}
                placeholder="e.g. JE-{location}-{report_date}"
              />
              {docPreview && (
                <p className="text-xs text-gray-600 italic mt-1 truncate">Preview: {docPreview}</p>
              )}
            </div>

            {scanFieldChips.length > 0 ? (
              <div>
                <button
                  type="button"
                  onClick={() => setFieldsExpanded(!fieldsExpanded)}
                  className="text-xs text-gray-400 hover:text-white cursor-pointer flex items-center gap-1 mb-1.5"
                >
                  <span className="text-xs">{fieldsExpanded ? '▾' : '▸'}</span>
                  {fieldsExpanded ? 'Hide available fields' : `Show available fields (${scanFieldChips.length})`}
                </button>
                {fieldsExpanded && (
                  <>
                    <div className="text-xs text-gray-500 mb-1.5">
                      Click to insert into Memo · <span className="text-purple-400">#</span> to insert into Doc #:
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {scanFieldChips.map((chip) => (
                        <div key={chip.normalized} className="flex rounded overflow-hidden text-xs border border-gray-600">
                          <button
                            type="button"
                            onClick={() => insertAtCursor(memoTextareaRef.current, `{${chip.normalized}}`, memoTemplate, setMemoTemplate)}
                            className="px-2 py-0.5 bg-gray-700 hover:bg-cyan-800 text-gray-300 hover:text-white transition-colors"
                            title={`Insert {${chip.normalized}} into Memo`}
                          >
                            {chip.original}
                          </button>
                          <button
                            type="button"
                            onClick={() => insertAtCursor(docInputRef.current, `{${chip.normalized}}`, docNumberTemplate, setDocNumberTemplate)}
                            className="px-1.5 py-0.5 bg-gray-800 hover:bg-purple-900 text-gray-500 hover:text-purple-300 transition-colors border-l border-gray-600"
                            title={`Insert {${chip.normalized}} into Doc #`}
                          >
                            #
                          </button>
                        </div>
                      ))}
                    </div>
                  </>
                )}
              </div>
            ) : (
              <p className="text-xs text-gray-600">Scan a Toast report first to see available field chips.</p>
            )}
          </div>
        )}
      </div>

      {(isBill || isVendorCredit) && selectedTemplateId && (
        <ProductMappingSection jwt={jwt} templateId={selectedTemplateId} />
      )}

      {(isBill || isVendorCredit) && selectedTemplateId && (
        <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
          <button
            type="button"
            onClick={() => setLineItemMappingOpen((current) => !current)}
            className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-700/50 transition-colors"
          >
            <span className="text-xs font-semibold text-gray-300">Column Roles — Line Items</span>
            <span className="text-gray-500 text-xs">{lineItemMappingOpen ? '▲' : '▼'}</span>
          </button>
          {lineItemMappingOpen ? (
            <div className="px-3 pb-3 space-y-3 border-t border-gray-700/60 pt-3">
              <p className="text-xs text-gray-400">Tell Nest which spreadsheet columns hold product names, amounts, etc.</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {LINE_ITEM_COLUMN_ROLES.map((role) => (
                  <div key={role.key}>
                    <div className="text-xs text-gray-400 mb-1">
                      {role.label}{role.required ? ' *' : ''}
                    </div>
                    <select
                      value={localColMap[role.key] ?? ''}
                      onChange={(e) => setLocalColMap((prev) => ({ ...prev, [role.key]: e.target.value }))}
                      className="w-full bg-gray-900 border border-gray-700 text-white text-sm rounded px-2 py-1.5 focus:outline-none focus:border-cyan-500"
                    >
                      <option value="">Select column</option>
                      {lineItemHeaders.map((header) => (
                        <option key={header} value={header}>{header}</option>
                      ))}
                    </select>
                  </div>
                ))}
              </div>
              <div className="flex flex-wrap gap-2 items-center">
                <button
                  type="button"
                  onClick={() => void saveLineItemColumnMappings()}
                  className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white rounded px-3 py-1.5"
                >
                  Save Column Roles
                </button>
                <div className="text-xs text-gray-400">
                  Current: {Object.entries(localColMap).filter(([, value]) => value).length} selected
                </div>
              </div>
            </div>
          ) : (
            <div className="px-3 pb-3 pt-3 border-t border-gray-700/60 flex flex-wrap gap-2">
              {Object.entries(localColMap).filter(([, value]) => value).map(([key, value]) => (
                <span key={key} className="rounded-full bg-gray-900 border border-gray-700 text-gray-300 text-[11px] px-2 py-1">
                  {LINE_ITEM_COLUMN_ROLES.find((role) => role.key === key)?.label ?? key}: {value}
                </span>
              ))}
            </div>
          )}
        </div>
      )}

      {activeScanEntry && activeScanEntry.lineItems.length > 0 && (isBill || isVendorCredit) && (
        <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
          <div className="px-3 py-2 bg-gray-900/80 border-b border-gray-700">
            <div className="text-xs font-semibold text-gray-300">Scanned Line Items</div>
            <div className="text-xs text-gray-500">Review all detected invoice items before mapping.</div>
          </div>
          <div className="max-h-[250px] overflow-y-auto">
            <table className="min-w-full text-left text-xs text-gray-200">
              <thead className="bg-gray-900 text-gray-400">
                <tr>
                  <th className="px-3 py-2 font-medium">#</th>
                  <th className="px-3 py-2 font-medium">Description</th>
                  <th className="px-3 py-2 font-medium">Qty</th>
                  <th className="px-3 py-2 font-medium">Unit Price</th>
                  <th className="px-3 py-2 font-medium">Total</th>
                </tr>
              </thead>
              <tbody>
                {activeScanEntry.lineItems.map((lineItem, index) => (
                  <tr key={index} className={index % 2 === 0 ? 'bg-gray-800' : 'bg-gray-900'}>
                    <td className="px-3 py-2 align-top text-gray-300">{index + 1}</td>
                    <td className="px-3 py-2 align-top text-gray-100 break-words">{lineItem.description ?? ''}</td>
                    <td className="px-3 py-2 align-top text-gray-300">{lineItem.quantity ?? ''}</td>
                    <td className="px-3 py-2 align-top text-gray-300">{lineItem.unitPrice ?? ''}</td>
                    <td className="px-3 py-2 align-top text-gray-300">{lineItem.total ?? ''}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="px-3 py-2 border-t border-gray-700 bg-gray-900/80 text-xs text-gray-400">
            {activeScanEntry.lineItems.length} line item{activeScanEntry.lineItems.length === 1 ? '' : 's'} detected
          </div>
        </div>
      )}

      {(isBill || isVendorCredit) && activeScanEntry && activeScanEntry.lineItems.length > 1 && (
        <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
          <button
            type="button"
            onClick={() => setLineItemFieldsOpen((prev) => !prev)}
            className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-700/50 transition-colors"
          >
            <span className="text-xs font-semibold text-gray-300">
              📄 Line Item Fields ({activeScanEntry.lineItems.length} line items)
            </span>
            <span className="text-gray-400 text-xs">
              {lineItemFieldsOpen ? '▲' : '▼'}
            </span>
          </button>
          {lineItemFieldsOpen && (
            <div className="px-3 pb-3 space-y-3">
              <p className="text-xs text-gray-400">
                Each field below shows values from all scanned line items. The mapping dropdown shows one copy per field type — it applies to all line items.
              </p>
              <div className="grid gap-3 sm:grid-cols-2">
                {(['description', 'quantity', 'unitPrice', 'total'] as const).map((field) => (
                  <div key={field}>
                    <div className="text-xs text-gray-400 mb-1 capitalize">
                      {field === 'unitPrice' ? 'Unit Price' : field}
                    </div>
                    <div className="text-xs text-gray-300">
                      {activeScanEntry.lineItems
                        .map((item) => item[field])
                        .filter((v) => v && String(v).trim() !== '')
                        .map((v, i, arr) => (
                          <span key={i}>
                            {String(v)}
                            {i < arr.length - 1 ? ', ' : ''}
                          </span>
                        ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {isBill && renderBillHeader()}
      {isVendorCredit && renderVendorCreditHeader()}
      {(
        loading ? (
          <DashboardSkeleton type="list" rows={3} />
        ) : localMappings.length === 0 ? (
          <EmptyState
            icon="🗂️"
            title="No mappings yet"
            description={onboardingStep === 3
              ? 'Create a mapping template to translate your POS data into QuickBooks journal entries'
              : 'Add a mapping or use Auto-Detect to get started.'}
            action={{ label: 'Add mapping', onClick: addMapping }}
          />
        ) : (
          <MappingTable
            localMappings={localMappings}
            accountOptions={accountOptions}
            accounts={accounts}
            classOptions={classOptions}
            taxCodeOptions={taxCodeOptions}
            scanFieldOptions={scanFieldOptions}
            entityOptions={buildEntityOptions('')}
            saving={saving}
            deleting={deleting}
            onUpdate={updateMapping}
            onSave={saveMapping}
            onDelete={deleteMapping}
            onToggleExpand={toggleExpand}
            onAddMapping={addMapping}
            isBill={isBill}
            isVendorCredit={isVendorCredit}
          />
        )
      )}

      {localMappings.length > 0 && (
        <div className="border-t border-gray-700 pt-3 space-y-2">
          {selectedTemplate?.transactionType === 'JOURNAL_ENTRY' && (
            <div className={`flex items-center justify-between text-xs px-3 py-2 rounded-lg ${
              isBalanced ? 'bg-green-900/30 border border-green-700' : 'bg-red-900/30 border border-red-700'
            }`}>
              <span className={isBalanced ? 'text-green-400' : 'text-red-400'}>
                {isBalanced ? '✓ Balanced' : '⚠️ Unbalanced'}
              </span>
              <span className="text-gray-400 font-mono">
                Dr ${totalDebits.toFixed(2)} / Cr ${totalCredits.toFixed(2)}
                {!isBalanced && ` (diff: $${Math.abs(diff).toFixed(2)})`}
              </span>
            </div>
          )}
          <div className="flex gap-2">
            <button
              onClick={() => {
                localMappings.filter((mapping) => mapping.isDirty).forEach((mapping, index) => void saveMapping(mapping, index));
              }}
              disabled={!localMappings.some((mapping) => mapping.isDirty)}
              className="flex-1 text-xs bg-cyan-700 hover:bg-cyan-600 disabled:opacity-40 text-white py-2 rounded-lg transition-colors"
            >
              💾 Save All Changes
            </button>
            <button
              onClick={() => onTabChange('preview')}
              className="flex-1 text-xs bg-gray-700 hover:bg-gray-600 text-gray-300 py-2 rounded-lg transition-colors"
            >
              📋 Preview {getPreviewLabel()} →
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api, ApiError } from '../lib/api';
import { extractLineItems, getAutoFillSummary } from '../lib/column-extractor';
import { useLocations } from '../hooks/useLocations';
import { useQuickBooks } from '../hooks/useQuickBooks';
import { useQBContext } from '../contexts/QBContext';
import SearchableSelect from './SearchableSelect';
import SmartDatePicker from './SmartDatePicker';
import ErrorCard from './shared/ErrorCard';
import type { ExtractedLineItem, ScanData, ScanEntry, Mapping, Template } from '../../types';
import type { SelectOption } from './SearchableSelect';
import type { QBAccount } from '../types/qb';
import { decodeMapping } from '../lib/je-builder';
import { parseNumericValue } from '../lib/parse-numeric-value';

interface BillLine {
  localId: string;
  accountId: string;
  accountName: string;
  description: string;
  classId: string;
  taxCodeId: string;
  amount: string;
}

function newLine(overrides?: Partial<BillLine>): BillLine {
  return {
    localId: `line-${Date.now()}-${Math.random()}`,
    accountId: '',
    accountName: '',
    description: '',
    classId: '',
    taxCodeId: '',
    amount: '',
    ...overrides,
  };
}

function toYMD(date: Date): string {
  return date.toISOString().split('T')[0]!;
}

function parseScanDate(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  const trimmed = raw.trim();
  if (!trimmed) return undefined;

  const textual = Date.parse(trimmed);
  if (!isNaN(textual)) {
    return toYMD(new Date(textual));
  }

  const slashMatch = trimmed.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (slashMatch) {
    const [, numA, numB, yearStr] = slashMatch;
    let year = yearStr.length === 2 ? 2000 + parseInt(yearStr, 10) : parseInt(yearStr, 10);
    const a = parseInt(numA, 10);
    const b = parseInt(numB, 10);

    if (a > 12) {
      return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
    }
    if (b > 12) {
      return `${year}-${String(a).padStart(2, '0')}-${String(b).padStart(2, '0')}`;
    }
    return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
  }

  return undefined;
}

function fmt(amount: number): string {
  return amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

interface Props {
  jwt: string;
  scanData: ScanData | null;
  activeScanEntry?: ScanEntry | null;
  selectedLocationId: string;
  scanRecordId?: string | null;
  selectedTemplate?: Template | null;
  onNavigateToPayments?: () => void;
}

export default function BillPreviewForm({
  jwt,
  scanData,
  activeScanEntry,
  selectedLocationId,
  scanRecordId,
  selectedTemplate,
  onNavigateToPayments,
}: Props) {
  const { status, connect } = useQuickBooks(jwt);
  const { locations } = useLocations(jwt);
  const {
    accounts,
    classes,
    vendors,
    taxCodes,
    terms,
    listsLoaded,
    listsLoading,
    listsError,
    syncAllLists,
  } = useQBContext();

  const today = toYMD(new Date());
  const [txnDate, setTxnDate] = useState(today);
  const [vendorRef, setVendorRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [apAccountRef, setApAccountRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [termsRef, setTermsRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [dueDate, setDueDate] = useState(today);
  const [memo, setMemo] = useState('');
  const [docNumber, setDocNumber] = useState('');
  const [lines, setLines] = useState<BillLine[]>([newLine(), newLine()]);
  const [savedMappings, setSavedMappings] = useState<Mapping[]>([]);
  const [mappingsLoaded, setMappingsLoaded] = useState(false);
  const [ruleTransformedLineItems, setRuleTransformedLineItems] = useState<Record<string, string>[] | null>(null);
  const [autoFillSummary, setAutoFillSummary] = useState<{ total: number; mapped: number; unmapped: number } | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ id: string; txnDate: string; docNumber?: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);

  const accountsRef = useRef(accounts);
  accountsRef.current = accounts;
  const userHasEditedLinesRef = useRef(false);

  const locId = selectedLocationId || locations[0]?.id || '';

  useEffect(() => {
    userHasEditedLinesRef.current = false;
  }, [activeScanEntry]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    if (!selectedTemplate?.columnMappings || !selectedTemplate?.id) return;
    if (!jwt || !locId) return;
    if (userHasEditedLinesRef.current) return;

    let cancelled = false;
    (async () => {
      try {
        const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
        if (cancelled) return;
        const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
        const extracted = extractLineItems({
          lineItems: itemsToExtract,
          columnMappings: selectedTemplate.columnMappings,
          productMappings,
          defaultPostingType: 'Credit',
        });
        if (cancelled) return;

        setLines(extracted.map((item) => newLine({
          accountId: item.accountId,
          accountName: item.accountName || accountsRef.current.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
          description: item.description,
          classId: item.classId ?? '',
          taxCodeId: item.taxCodeId ?? '',
          amount: item.amount.toFixed(2),
        })));
        setAutoFillSummary(getAutoFillSummary(extracted));
      } catch {
        // silent fallback: user can still click Auto-fill
      }
    })();

    return () => { cancelled = true; };
  }, [activeScanEntry, selectedTemplate, jwt, locId, ruleTransformedLineItems]);

  useEffect(() => {
    if (!listsLoaded && !listsLoading && !listsError) {
      void syncAllLists();
    }
  }, [listsLoaded, listsLoading, listsError, syncAllLists]);

  useEffect(() => {
    if (!jwt || !locId) return;
    setMappingsLoaded(false);
    api.getMappings(jwt, locId)
      .then((mappings) => {
        setSavedMappings(mappings);
        setMappingsLoaded(true);
      })
      .catch((err) => {
        console.error('[Bill Preview] Failed to load mappings:', err);
        setMappingsLoaded(true);
      });
  }, [jwt, locId]);

  useEffect(() => {
    if (!jwt || !locId || !activeScanEntry?.lineItems?.length) return;
    if (!selectedTemplate?.id) return;

    const apply = async () => {
      try {
        const rules = await api.getRules(jwt, locId, selectedTemplate?.id);
        const activeRules = rules.filter((r) => r.isActive);
        if (activeRules.length === 0) {
          setRuleTransformedLineItems(null);
          return;
        }

        const result = await api.applyRules(jwt, {
          lineItems: activeScanEntry.lineItems,
          rules: activeRules,
        });
        if (result.type === 'lineItems') {
          setRuleTransformedLineItems(result.data);
        }
      } catch (err) {
        console.error('[Bill Preview] Failed to apply rules:', err);
      }
    };

    void apply();
  }, [jwt, locId, activeScanEntry, selectedTemplate?.id]);

  useEffect(() => {
    if (!scanData || !locId) return;
    const loc = locations.find((location) => location.id === locId);
    if (!loc) return;
    const memoTemplate = loc.memoTemplate;
    const docNumberTemplate = loc.docNumberTemplate;

    if (memoTemplate) {
      setMemo((prev) => prev || memoTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }

    if (docNumberTemplate) {
      setDocNumber((prev) => prev || docNumberTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }
  }, [scanData, locId, locations]);

  useEffect(() => {
    if (!selectedTemplate || selectedTemplate.transactionType !== 'BILL') return;
    const defaults = selectedTemplate.defaults as Record<string, { value: string; name?: string } | null> | null;
    if (!defaults) return;

    if (defaults.vendorRef) setVendorRef(defaults.vendorRef);
    if (defaults.apAccountRef) setApAccountRef(defaults.apAccountRef);
    if (defaults.termsRef) setTermsRef(defaults.termsRef);
    if (defaults.dueDate?.value) setDueDate(defaults.dueDate.value);
    if (defaults.memo?.value) setMemo(defaults.memo.value);
    if (defaults.docNumber?.value) setDocNumber(defaults.docNumber.value);
  }, [selectedTemplate]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    const h = activeScanEntry.header;
    if (!h || !Object.keys(h).length) return;

    setVendorRef((prev) => {
      if (prev.value) return prev;
      const vendorName = (h.vendor || '').trim();
      if (!vendorName) return prev;
      const lower = vendorName.toLowerCase();
      const match = vendors.find((v) => {
        if (v.DisplayName.toLowerCase() === lower) return true;
        if (v.CompanyName?.toLowerCase() === lower) return true;
        if (v.DisplayName.toLowerCase().includes(lower)) return true;
        if (v.CompanyName?.toLowerCase()?.includes(lower)) return true;
        if (lower.includes(v.DisplayName.toLowerCase())) return true;
        if (v.CompanyName && lower.includes(v.CompanyName.toLowerCase())) return true;
        return false;
      });
      if (match) return { value: match.Id, name: match.DisplayName };
      return prev;
    });

    setDocNumber((prev) => {
      if (prev) return prev;
      return (h.invoiceNumber || '').trim() || prev;
    });

    const parsedDate = parseScanDate(h.invoiceDate);
    if (parsedDate) {
      setTxnDate((prev) => {
        if (prev && prev !== toYMD(new Date())) return prev;
        return parsedDate;
      });
    }

    const parsedDue = parseScanDate(h.dueDate);
    if (parsedDue) {
      setDueDate((prev) => {
        if (prev && prev !== toYMD(new Date())) return prev;
        return parsedDue;
      });
    }

    if (h.total) {
      setMemo((prev) => {
        if (prev) return prev;
        return `Invoice total: ${h.total}`;
      });
    }
  }, [activeScanEntry, vendors]);

  useEffect(() => {
    if (!mappingsLoaded) return;
    if (activeScanEntry?.source === 'image' || activeScanEntry?.source === 'pdf') return;
    const decoded = savedMappings.map(decodeMapping);
    const scanFields: Record<string, number> = activeScanEntry
      ? Object.fromEntries(
        Object.entries(activeScanEntry.lineItems?.[0] ?? {})
          .map(([key, value]) => [key, parseNumericValue(value)])
          .filter(([, v]) => !Number.isNaN(v)),
      ) as Record<string, number>
      : scanData ?? {};

    const billLines = Object.entries(scanFields)
      .filter(([, amount]) => amount !== 0)
      .map(([field, amount]) => {
        const mapping = decoded.find((m) => m.sourceField === field);
        const accountId = mapping?.accountId ?? '';
        const accountName = accountsRef.current.find((a) => a.Id === accountId)?.FullyQualifiedName ?? '';
        return newLine({
          accountId,
          accountName,
          description: mapping?.description ?? field,
          classId: mapping?.classId ?? '',
          amount: Math.abs(amount).toFixed(2),
        });
      });

    if (billLines.length > 0) {
      setLines(billLines);
    }
  }, [activeScanEntry, scanData, savedMappings, mappingsLoaded]);

  const vendorOptions = useMemo(() =>
    vendors
      .filter((vendor) => vendor.Active)
      .map((vendor) => ({ value: vendor.Id, label: vendor.DisplayName, subtitle: vendor.CompanyName ?? undefined })),
    [vendors],
  );

  const apAccountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType })),
    [accounts],
  );

  const accountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType, group: account.Classification || account.AccountType })),
    [accounts],
  );

  const classOptions = useMemo(() =>
    classes.filter((item) => item.Active).map((item) => ({ value: item.Id, label: item.FullyQualifiedName })),
    [classes],
  );

  const taxCodeOptions = useMemo(() =>
    taxCodes.filter((item) => item.Active).map((item) => ({ value: item.Id, label: item.Name, subtitle: item.Description })),
    [taxCodes],
  );

  const updateLine = (localId: string, patch: Partial<BillLine>) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.map((line) => (line.localId === localId ? { ...line, ...patch } : line)));
  };

  const removeLine = (localId: string) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.filter((line) => line.localId !== localId));
  };

  const addLine = () => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => [...prev, newLine()]);
  };

  const effectiveLines = lines;
  const totalAmount = effectiveLines.reduce((sum, line) => sum + (parseFloat(line.amount) || 0), 0);
  const unmappedCount = effectiveLines.filter((line) => parseFloat(line.amount) > 0 && !line.accountId).length;
  const hasAmount = effectiveLines.some((line) => parseFloat(line.amount) > 0);
  const allMapped = unmappedCount === 0 && hasAmount;
  const hasHeader = Boolean(vendorRef.value && apAccountRef.value);

  const handleClearAll = () => {
    setTxnDate(today);
    setVendorRef({ value: '' });
    setApAccountRef({ value: '' });
    setTermsRef({ value: '' });
    setDueDate(today);
    setMemo('');
    setDocNumber('');
    setLines([newLine(), newLine()]);
    userHasEditedLinesRef.current = false;
    setError(null);
    setSyncResult(null);
    setAutoFillSummary(null);
    setRuleTransformedLineItems(null);
  };

  const handleAutoFill = useCallback(async () => {
    if (!activeScanEntry?.lineItems?.length) {
      setError('No scan line items available to auto-fill');
      return;
    }
    if (!selectedTemplate?.columnMappings) {
      setError('Template column mappings are required for auto-fill');
      return;
    }
    if (!selectedTemplate?.id) return;

    setError(null);

    try {
      const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
      const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
      const extracted = extractLineItems({
        lineItems: itemsToExtract,
        columnMappings: selectedTemplate.columnMappings,
        productMappings,
        defaultPostingType: 'Credit',
      });

      const billLines = extracted.map((item) => newLine({
        accountId: item.accountId,
        accountName: item.accountName || accounts.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
        description: item.description,
        classId: item.classId ?? '',
        taxCodeId: item.taxCodeId ?? '',
        amount: item.amount.toFixed(2),
      }));

      setLines(billLines);
      setAutoFillSummary(getAutoFillSummary(extracted));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Auto-fill failed');
    }
  }, [activeScanEntry, accounts, jwt, selectedTemplate]);

  const handleSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const billLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
          taxCodeRef: line.taxCodeId ? { value: line.taxCodeId } : undefined,
        }));

      const result = await api.createBill(
        jwt,
        txnDate,
        vendorRef,
        apAccountRef,
        termsRef.value ? termsRef : undefined,
        dueDate || undefined,
        memo || undefined,
        docNumber || undefined,
        billLines,
        scanRecordId ?? undefined,
      ) as { billId: string; txnDate: string; docNumber?: string };

        setSyncResult({ id: result.billId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Bill sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, apAccountRef, dueDate, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, termsRef, txnDate, docNumber, vendorRef]);

  const handleForceSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const billLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
          taxCodeRef: line.taxCodeId ? { value: line.taxCodeId } : undefined,
        }));

      const result = await api.createBill(
        jwt,
        txnDate,
        vendorRef,
        apAccountRef,
        termsRef.value ? termsRef : undefined,
        dueDate || undefined,
        memo || undefined,
        docNumber || undefined,
        billLines,
        scanRecordId ?? undefined,
        true,
      ) as { billId: string; txnDate: string; docNumber?: string };

      setSyncResult({ id: result.billId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Bill sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, apAccountRef, dueDate, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, termsRef, txnDate, docNumber, vendorRef]);

  if (!status.connected) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center px-4">
        <div className="text-4xl mb-3">🔗</div>
        <p className="text-gray-400 text-sm mb-1">QuickBooks not connected</p>
        <p className="text-gray-600 text-xs mb-4">Connect QuickBooks in Settings to sync bills</p>
        <button onClick={connect} className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white px-4 py-2 rounded-lg">
          Connect QuickBooks
        </button>
      </div>
    );
  }

  return (
    <div className="p-3 flex flex-col gap-3">
      <div className="flex items-center gap-2 text-xs px-3 py-1.5 bg-green-900/20 border border-green-800 rounded-lg">
        <span className="text-green-400">✅ QB Connected</span>
        <span className="text-gray-600 truncate">{status.realmId}</span>
        <button
          onClick={() => void syncAllLists()}
          disabled={listsLoading}
          className="ml-auto text-gray-500 hover:text-gray-300 transition-colors"
          title="Refresh QB lists"
        >
          {listsLoading ? '…' : '↻'}
        </button>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 grid grid-cols-2 gap-3">
        <div>
          <div className="text-xs text-gray-500 mb-1">Transaction Date</div>
          <SmartDatePicker value={txnDate} onChange={setTxnDate} />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">Vendor</div>
          <SearchableSelect
            options={vendorOptions}
            value={vendorRef.value}
            onChange={(value) => {
              const selected = vendors.find((v) => v.Id === value);
              setVendorRef({ value, name: selected?.DisplayName });
            }}
            placeholder="Select vendor…"
          />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">AP Account</div>
          <SearchableSelect
            options={apAccountOptions}
            value={apAccountRef.value}
            onChange={(value) => {
              const selected = accounts.find((a) => a.Id === value);
              setApAccountRef({ value, name: selected?.FullyQualifiedName });
            }}
            placeholder="Select AP account…"
          />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">Due Date</div>
          <SmartDatePicker value={dueDate} onChange={setDueDate} />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Terms</div>
          {terms.length > 0 ? (
            <select
              className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
              value={termsRef.value}
              onChange={(e) => {
                const selected = terms.find((term) => term.Id === e.target.value);
                setTermsRef({ value: e.target.value, name: selected?.Name });
              }}
            >
              <option value="">Select terms...</option>
              {terms.map((term) => (
                <option key={term.Id} value={term.Id}>{term.Name}</option>
              ))}
            </select>
          ) : (
            <input
              className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
              value={termsRef.value}
              onChange={(e) => setTermsRef({ value: e.target.value })}
              placeholder="Terms reference…"
            />
          )}
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Memo / Private Note</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={memo}
            onChange={(e) => setMemo(e.target.value)}
            placeholder={`Nest sync — ${txnDate}`}
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Bill No.</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={docNumber}
            onChange={(e) => setDocNumber(e.target.value)}
            placeholder="Optional bill number"
          />
        </div>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
        <div className="flex flex-col gap-2 px-3 py-3 border-b border-gray-700/60 sm:flex-row sm:items-center sm:justify-between">
          <button
            type="button"
            onClick={() => void handleAutoFill()}
            disabled={!activeScanEntry?.lineItems?.length || !selectedTemplate?.columnMappings}
            className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded px-3 py-1.5"
          >
            Auto-fill from Scan
          </button>
          {autoFillSummary ? (
            <div className="text-xs text-gray-300">
              {autoFillSummary.total} items: {autoFillSummary.mapped} mapped, {autoFillSummary.unmapped} unmapped
            </div>
          ) : null}
        </div>
        <div className="overflow-x-auto overflow-y-auto max-h-[320px]">
          <table className="w-full text-xs border-collapse min-w-[680px]">
            <thead>
              <tr className="border-b border-gray-700 bg-gray-700/50">
                <th className="text-gray-400 font-medium text-left px-2 py-2 w-8">#</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[180px]">Account</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[160px]">Description</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[120px]">Class</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[120px]">Tax Code</th>
                <th className="text-gray-400 font-medium text-right px-2 py-2 w-24">Amount</th>
                <th className="text-gray-400 font-medium text-center px-1 py-2 w-8"></th>
              </tr>
            </thead>
            <tbody>
              {effectiveLines.map((line, idx) => (
                <tr key={line.localId} className={`border-b border-gray-700/60 ${idx % 2 === 1 ? 'bg-gray-800/40' : ''}`}>
                  <td className="px-2 py-1 text-gray-600 text-center text-xs">{idx + 1}</td>
                  <td className="px-1 py-1 min-w-[180px] max-w-[240px]">
                    <SearchableSelect
                      options={accountOptions}
                      value={line.accountId}
                      onChange={(value) => {
                        const account = accounts.find((a) => a.Id === value);
                        updateLine(line.localId, { accountId: value, accountName: account?.FullyQualifiedName ?? '' });
                      }}
                      placeholder="Account…"
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[160px]">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 focus:border-cyan-500 focus:outline-none"
                      value={line.description}
                      onChange={(e) => updateLine(line.localId, { description: e.target.value })}
                      placeholder="Description…"
                      maxLength={4000}
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[120px] max-w-[160px]">
                    <SearchableSelect
                      options={classOptions}
                      value={line.classId}
                      onChange={(value) => updateLine(line.localId, { classId: value })}
                      placeholder="Class…"
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[120px] max-w-[160px]">
                    <SearchableSelect
                      options={taxCodeOptions}
                      value={line.taxCodeId}
                      onChange={(value) => updateLine(line.localId, { taxCodeId: value })}
                      placeholder="Tax Code…"
                    />
                  </td>
                  <td className="px-1 py-1 text-right w-24">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 text-right focus:border-cyan-500 focus:outline-none"
                      value={line.amount}
                      onChange={(e) => updateLine(line.localId, { amount: e.target.value })}
                      placeholder="0.00"
                      inputMode="decimal"
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <button
                      type="button"
                      onClick={() => removeLine(line.localId)}
                      className="text-gray-400 hover:text-red-400"
                      disabled={effectiveLines.length <= 1}
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="border-t border-gray-600 bg-gray-700/30 font-semibold">
                <td className="px-2 py-2 text-gray-500">{effectiveLines.length}</td>
                <td colSpan={4} className="px-2 py-2 text-gray-500">Total</td>
                <td className="px-2 py-2 text-right font-mono text-blue-300">${fmt(totalAmount)}</td>
                <td />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <button
        type="button"
        onClick={addLine}
        className="w-full text-xs text-gray-500 hover:text-gray-300 border border-dashed border-gray-700 hover:border-gray-500 py-1.5 rounded-lg transition-colors"
      >
        + Add Line
      </button>

      {duplicateWarning && (
        <ErrorCard
          variant="warning"
          message={duplicateWarning}
          onDismiss={() => setDuplicateWarning(null)}
          onRetry={handleForceSync}
        />
      )}
      {error && (
        <div className="bg-red-900/40 border border-red-700 text-red-300 text-xs rounded-lg px-3 py-2">
          {error}
        </div>
      )}
      {syncResult && (
        <div className="bg-green-900/40 border border-green-700 text-green-300 text-xs rounded-lg px-3 py-2 space-y-1.5">
          <div>✅ Bill created — <span className="font-mono">{syncResult.id}</span></div>
          {syncResult.docNumber && <div>Bill # {syncResult.docNumber}</div>}
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => navigator.clipboard.writeText(syncResult.id).catch(() => {})}
              className="text-xs text-cyan-400 hover:text-cyan-300 border border-cyan-800 hover:border-cyan-600 px-2 py-0.5 rounded transition-colors"
            >
              Copy ID
            </button>
            <a
              href={`${status.environment === 'sandbox' ? 'https://app.sandbox.qbo.intuit.com' : 'https://app.qbo.intuit.com'}/app/bill?txnId=${syncResult.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs text-cyan-400 hover:underline"
            >
              View in QuickBooks ↗
            </a>
            {onNavigateToPayments && (
              <button
                type="button"
                onClick={onNavigateToPayments}
                className="text-xs text-white bg-cyan-700 hover:bg-cyan-600 px-2 py-0.5 rounded transition-colors"
              >
                Pay this bill → Payments
              </button>
            )}
          </div>
        </div>
      )}

      <div className="flex gap-2">
        <button
          type="button"
          onClick={handleClearAll}
          className="px-3 py-2 text-xs text-red-400 border border-red-800 hover:bg-red-900/20 rounded-lg transition-colors"
        >
          Clear All
        </button>
        <button
          type="button"
          onClick={() => void handleSync()}
          disabled={syncing || !hasHeader || !allMapped || !hasAmount}
          className="flex-1 py-2.5 bg-green-600 hover:bg-green-500 disabled:bg-gray-700 disabled:text-gray-500 text-white text-sm font-bold rounded-lg transition-colors"
        >
          {syncing
            ? 'Syncing Bill…'
            : !hasHeader
              ? '⚠️ Vendor and AP account required'
              : !hasAmount
                ? '⚠️ Add bill amounts'
                : !allMapped
                  ? '⚠️ Assign all line accounts'
                  : '⚡ Sync Bill to QuickBooks'}
        </button>
      </div>
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api, ApiError } from '../lib/api';
import { extractLineItems, getAutoFillSummary } from '../lib/column-extractor';
import { useLocations } from '../hooks/useLocations';
import { useQuickBooks } from '../hooks/useQuickBooks';
import { useQBContext } from '../contexts/QBContext';
import SearchableSelect from './SearchableSelect';
import SmartDatePicker from './SmartDatePicker';
import ErrorCard from './shared/ErrorCard';
import type { ExtractedLineItem, ScanData, ScanEntry, Mapping, Template } from '../../types';
import type { SelectOption } from './SearchableSelect';
import type { QBAccount } from '../types/qb';
import { decodeMapping } from '../lib/je-builder';
import { parseNumericValue } from '../lib/parse-numeric-value';

interface CreditLine {
  localId: string;
  accountId: string;
  accountName: string;
  description: string;
  classId: string;
  taxCodeId: string;
  amount: string;
}

function newLine(overrides?: Partial<CreditLine>): CreditLine {
  return {
    localId: `line-${Date.now()}-${Math.random()}`,
    accountId: '',
    accountName: '',
    description: '',
    classId: '',
    taxCodeId: '',
    amount: '',
    ...overrides,
  };
}

function toYMD(date: Date): string {
  return date.toISOString().split('T')[0]!;
}

function parseScanDate(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  const trimmed = raw.trim();
  if (!trimmed) return undefined;

  const textual = Date.parse(trimmed);
  if (!isNaN(textual)) {
    return toYMD(new Date(textual));
  }

  const slashMatch = trimmed.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (slashMatch) {
    const [, numA, numB, yearStr] = slashMatch;
    let year = yearStr.length === 2 ? 2000 + parseInt(yearStr, 10) : parseInt(yearStr, 10);
    const a = parseInt(numA, 10);
    const b = parseInt(numB, 10);

    if (a > 12) {
      return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
    }
    if (b > 12) {
      return `${year}-${String(a).padStart(2, '0')}-${String(b).padStart(2, '0')}`;
    }
    return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
  }

  return undefined;
}

function fmt(amount: number): string {
  return amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

interface Props {
  jwt: string;
  scanData: ScanData | null;
  activeScanEntry?: ScanEntry | null;
  selectedLocationId: string;
  scanRecordId?: string | null;
  selectedTemplate?: Template | null;
}

export default function VendorCreditPreviewForm({
  jwt,
  scanData,
  activeScanEntry,
  selectedLocationId,
  scanRecordId,
  selectedTemplate,
}: Props) {
  const { status, connect } = useQuickBooks(jwt);
  const { locations } = useLocations(jwt);
  const {
    accounts,
    classes,
    vendors,
    taxCodes,
    listsLoaded,
    listsLoading,
    listsError,
    syncAllLists,
  } = useQBContext();

  const today = toYMD(new Date());
  const [txnDate, setTxnDate] = useState(today);
  const [vendorRef, setVendorRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [apAccountRef, setApAccountRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [memo, setMemo] = useState('');
  const [docNumber, setDocNumber] = useState('');
  const [lines, setLines] = useState<CreditLine[]>([newLine(), newLine()]);
  const [savedMappings, setSavedMappings] = useState<Mapping[]>([]);
  const [mappingsLoaded, setMappingsLoaded] = useState(false);
  const [ruleTransformedLineItems, setRuleTransformedLineItems] = useState<Record<string, string>[] | null>(null);
  const [autoFillSummary, setAutoFillSummary] = useState<{ total: number; mapped: number; unmapped: number } | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ id: string; txnDate: string; docNumber?: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);

  const accountsRef = useRef(accounts);
  accountsRef.current = accounts;
  const userHasEditedLinesRef = useRef(false);

  const locId = selectedLocationId || locations[0]?.id || '';

  useEffect(() => {
    userHasEditedLinesRef.current = false;
  }, [activeScanEntry]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    if (!selectedTemplate?.columnMappings || !selectedTemplate?.id) return;
    if (!jwt || !locId) return;
    if (userHasEditedLinesRef.current) return;

    let cancelled = false;
    (async () => {
      try {
        const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
        if (cancelled) return;
        const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
        const extracted = extractLineItems({
          lineItems: itemsToExtract,
          columnMappings: selectedTemplate.columnMappings,
          productMappings,
          defaultPostingType: 'Debit',
        });
        if (cancelled) return;

        setLines(extracted.map((item) => newLine({
          accountId: item.accountId,
          accountName: item.accountName || accountsRef.current.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
          description: item.description,
          classId: item.classId ?? '',
          taxCodeId: item.taxCodeId ?? '',
          amount: item.amount.toFixed(2),
        })));
        setAutoFillSummary(getAutoFillSummary(extracted));
      } catch {
        // silent fallback
      }
    })();

    return () => { cancelled = true; };
  }, [activeScanEntry, selectedTemplate, jwt, locId, ruleTransformedLineItems]);

  useEffect(() => {
    if (!listsLoaded && !listsLoading && !listsError) {
      void syncAllLists();
    }
  }, [listsLoaded, listsLoading, listsError, syncAllLists]);

  useEffect(() => {
    if (!jwt || !locId) return;
    setMappingsLoaded(false);
    api.getMappings(jwt, locId)
      .then((mappings) => {
        setSavedMappings(mappings);
        setMappingsLoaded(true);
      })
      .catch((err) => {
        console.error('[Vendor Credit Preview] Failed to load mappings:', err);
        setMappingsLoaded(true);
      });
  }, [jwt, locId]);

  useEffect(() => {
    if (!jwt || !locId || !activeScanEntry?.lineItems?.length) return;
    if (!selectedTemplate?.id) return;

    const apply = async () => {
      try {
        const rules = await api.getRules(jwt, locId, selectedTemplate?.id);
        const activeRules = rules.filter((r) => r.isActive);
        if (activeRules.length === 0) {
          setRuleTransformedLineItems(null);
          return;
        }

        const result = await api.applyRules(jwt, {
          lineItems: activeScanEntry.lineItems,
          rules: activeRules,
        });
        if (result.type === 'lineItems') {
          setRuleTransformedLineItems(result.data);
        }
      } catch (err) {
        console.error('[Vendor Credit Preview] Failed to apply rules:', err);
      }
    };

    void apply();
  }, [jwt, locId, activeScanEntry, selectedTemplate?.id]);

  useEffect(() => {
    if (!scanData || !locId) return;
    const loc = locations.find((location) => location.id === locId);
    if (!loc) return;
    const memoTemplate = loc.memoTemplate;
    const docNumberTemplate = loc.docNumberTemplate;

    if (memoTemplate) {
      setMemo((prev) => prev || memoTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }

    if (docNumberTemplate) {
      setDocNumber((prev) => prev || docNumberTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }
  }, [scanData, locId, locations]);

  useEffect(() => {
    if (!selectedTemplate || selectedTemplate.transactionType !== 'VENDOR_CREDIT') return;
    const defaults = selectedTemplate.defaults as Record<string, { value: string; name?: string } | null> | null;
    if (!defaults) return;

    if (defaults.vendorRef) setVendorRef(defaults.vendorRef);
    if (defaults.apAccountRef) setApAccountRef(defaults.apAccountRef);
    if (defaults.memo?.value) setMemo(defaults.memo.value);
    if (defaults.docNumber?.value) setDocNumber(defaults.docNumber.value);
  }, [selectedTemplate]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    const h = activeScanEntry.header;
    if (!h || !Object.keys(h).length) return;

    setVendorRef((prev) => {
      if (prev.value) return prev;
      const vendorName = (h.vendor || '').trim();
      if (!vendorName) return prev;
      const lower = vendorName.toLowerCase();
      const match = vendors.find((v) => {
        if (v.DisplayName.toLowerCase() === lower) return true;
        if (v.CompanyName?.toLowerCase() === lower) return true;
        if (v.DisplayName.toLowerCase().includes(lower)) return true;
        if (v.CompanyName?.toLowerCase()?.includes(lower)) return true;
        if (lower.includes(v.DisplayName.toLowerCase())) return true;
        if (v.CompanyName && lower.includes(v.CompanyName.toLowerCase())) return true;
        return false;
      });
      if (match) return { value: match.Id, name: match.DisplayName };
      return prev;
    });

    setDocNumber((prev) => {
      if (prev) return prev;
      return (h.invoiceNumber || '').trim() || prev;
    });

    const parsedDate = parseScanDate(h.invoiceDate);
    if (parsedDate) {
      setTxnDate((prev) => {
        if (prev && prev !== toYMD(new Date())) return prev;
        return parsedDate;
      });
    }

    if (h.total) {
      setMemo((prev) => {
        if (prev) return prev;
        return `Invoice total: ${h.total}`;
      });
    }
  }, [activeScanEntry, vendors]);

  useEffect(() => {
    if (!mappingsLoaded) return;
    if (activeScanEntry?.source === 'image' || activeScanEntry?.source === 'pdf') return;
    const decoded = savedMappings.map(decodeMapping);
    const scanFields: Record<string, number> = activeScanEntry
      ? Object.fromEntries(
        Object.entries(activeScanEntry.lineItems?.[0] ?? {})
          .map(([key, value]) => [key, parseNumericValue(value)])
          .filter(([, v]) => !Number.isNaN(v)),
      ) as Record<string, number>
      : scanData ?? {};

    const creditLines = Object.entries(scanFields)
      .filter(([, amount]) => amount !== 0)
      .map(([field, amount]) => {
        const mapping = decoded.find((m) => m.sourceField === field);
        const accountId = mapping?.accountId ?? '';
        const accountName = accountsRef.current.find((a) => a.Id === accountId)?.FullyQualifiedName ?? '';
        return newLine({
          accountId,
          accountName,
          description: mapping?.description ?? field,
          classId: mapping?.classId ?? '',
          amount: Math.abs(amount).toFixed(2),
        });
      });

    if (creditLines.length > 0) {
      setLines(creditLines);
    }
  }, [activeScanEntry, scanData, savedMappings, mappingsLoaded]);

  const vendorOptions = useMemo(() =>
    vendors
      .filter((vendor) => vendor.Active)
      .map((vendor) => ({ value: vendor.Id, label: vendor.DisplayName, subtitle: vendor.CompanyName ?? undefined })),
    [vendors],
  );

  const apAccountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType })),
    [accounts],
  );

  const accountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType, group: account.Classification || account.AccountType })),
    [accounts],
  );

  const classOptions = useMemo(() =>
    classes.filter((item) => item.Active).map((item) => ({ value: item.Id, label: item.FullyQualifiedName })),
    [classes],
  );

  const taxCodeOptions = useMemo(() =>
    taxCodes.filter((item) => item.Active).map((item) => ({ value: item.Id, label: item.Name, subtitle: item.Description })),
    [taxCodes],
  );

  const updateLine = (localId: string, patch: Partial<CreditLine>) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.map((line) => (line.localId === localId ? { ...line, ...patch } : line)));
  };

  const removeLine = (localId: string) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.filter((line) => line.localId !== localId));
  };

  const addLine = () => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => [...prev, newLine()]);
  };

  const effectiveLines = lines;
  const totalAmount = effectiveLines.reduce((sum, line) => sum + (parseFloat(line.amount) || 0), 0);
  const unmappedCount = effectiveLines.filter((line) => parseFloat(line.amount) > 0 && !line.accountId).length;
  const hasAmount = effectiveLines.some((line) => parseFloat(line.amount) > 0);
  const allMapped = unmappedCount === 0 && hasAmount;
  const hasHeader = Boolean(vendorRef.value && apAccountRef.value);

  const handleClearAll = () => {
    setTxnDate(today);
    setVendorRef({ value: '' });
    setApAccountRef({ value: '' });
    setMemo('');
    setDocNumber('');
    setLines([newLine(), newLine()]);
    userHasEditedLinesRef.current = false;
    setError(null);
    setSyncResult(null);
    setAutoFillSummary(null);
    setRuleTransformedLineItems(null);
  };

  const handleAutoFill = useCallback(async () => {
    if (!activeScanEntry?.lineItems?.length) {
      setError('No scan line items available to auto-fill');
      return;
    }
    if (!selectedTemplate?.columnMappings) {
      setError('Template column mappings are required for auto-fill');
      return;
    }
    if (!selectedTemplate?.id) return;

    setError(null);

    try {
      const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
      const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
      const extracted = extractLineItems({
        lineItems: itemsToExtract,
        columnMappings: selectedTemplate.columnMappings,
        productMappings,
        defaultPostingType: 'Debit',
      });

      const creditLines = extracted.map((item) => newLine({
        accountId: item.accountId,
        accountName: item.accountName || accounts.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
        description: item.description,
        classId: item.classId ?? '',
        taxCodeId: item.taxCodeId ?? '',
        amount: item.amount.toFixed(2),
      }));

      setLines(creditLines);
      setAutoFillSummary(getAutoFillSummary(extracted));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Auto-fill failed');
    }
  }, [activeScanEntry, accounts, jwt, selectedTemplate]);

  const handleSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const creditLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
          taxCodeRef: line.taxCodeId ? { value: line.taxCodeId } : undefined,
        }));

      const result = await api.createVendorCredit(
        jwt,
        vendorRef,
        txnDate,
        apAccountRef,
        creditLines,
        scanRecordId ?? undefined,
        memo || undefined,
        docNumber || undefined,
      ) as { vendorCreditId: string; txnDate: string; docNumber?: string };

      setSyncResult({ id: result.vendorCreditId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Vendor credit sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, apAccountRef, docNumber, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, txnDate, vendorRef]);

  const handleForceSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const creditLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
          taxCodeRef: line.taxCodeId ? { value: line.taxCodeId } : undefined,
        }));

      const result = await api.createVendorCredit(
        jwt,
        vendorRef,
        txnDate,
        apAccountRef,
        creditLines,
        scanRecordId ?? undefined,
        memo || undefined,
        docNumber || undefined,
        true,
      ) as { vendorCreditId: string; txnDate: string; docNumber?: string };

      setSyncResult({ id: result.vendorCreditId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Vendor credit sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, apAccountRef, docNumber, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, txnDate, vendorRef]);

  if (!status.connected) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center px-4">
        <div className="text-4xl mb-3">🔗</div>
        <p className="text-gray-400 text-sm mb-1">QuickBooks not connected</p>
        <p className="text-gray-600 text-xs mb-4">Connect QuickBooks in Settings to sync vendor credits</p>
        <button onClick={connect} className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white px-4 py-2 rounded-lg">
          Connect QuickBooks
        </button>
      </div>
    );
  }

  return (
    <div className="p-3 flex flex-col gap-3">
      <div className="flex items-center gap-2 text-xs px-3 py-1.5 bg-green-900/20 border border-green-800 rounded-lg">
        <span className="text-green-400">✅ QB Connected</span>
        <span className="text-gray-600 truncate">{status.realmId}</span>
        <button
          onClick={() => void syncAllLists()}
          disabled={listsLoading}
          className="ml-auto text-gray-500 hover:text-gray-300 transition-colors"
          title="Refresh QB lists"
        >
          {listsLoading ? '…' : '↻'}
        </button>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 grid grid-cols-2 gap-3">
        <div>
          <div className="text-xs text-gray-500 mb-1">Credit Date</div>
          <SmartDatePicker value={txnDate} onChange={setTxnDate} />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">Vendor</div>
          <SearchableSelect
            options={vendorOptions}
            value={vendorRef.value}
            onChange={(value) => {
              const selected = vendors.find((v) => v.Id === value);
              setVendorRef({ value, name: selected?.DisplayName });
            }}
            placeholder="Select vendor…"
          />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">AP Account</div>
          <SearchableSelect
            options={apAccountOptions}
            value={apAccountRef.value}
            onChange={(value) => {
              const selected = accounts.find((a) => a.Id === value);
              setApAccountRef({ value, name: selected?.FullyQualifiedName });
            }}
            placeholder="Select AP account…"
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Memo / Private Note</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={memo}
            onChange={(e) => setMemo(e.target.value)}
            placeholder={`Nest sync — ${txnDate}`}
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Credit No.</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={docNumber}
            onChange={(e) => setDocNumber(e.target.value)}
            placeholder="Optional credit number"
          />
        </div>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
        <div className="flex flex-col gap-2 px-3 py-3 border-b border-gray-700/60 sm:flex-row sm:items-center sm:justify-between">
          <button
            type="button"
            onClick={() => void handleAutoFill()}
            disabled={!activeScanEntry?.lineItems?.length || !selectedTemplate?.columnMappings}
            className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded px-3 py-1.5"
          >
            Auto-fill from Scan
          </button>
          {autoFillSummary ? (
            <div className="text-xs text-gray-300">
              {autoFillSummary.total} items: {autoFillSummary.mapped} mapped, {autoFillSummary.unmapped} unmapped
            </div>
          ) : null}
        </div>
        <div className="overflow-x-auto overflow-y-auto max-h-[320px]">
          <table className="w-full text-xs border-collapse min-w-[680px]">
            <thead>
              <tr className="border-b border-gray-700 bg-gray-700/50">
                <th className="text-gray-400 font-medium text-left px-2 py-2 w-8">#</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[180px]">Account</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[160px]">Description</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[120px]">Class</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[120px]">Tax Code</th>
                <th className="text-gray-400 font-medium text-right px-2 py-2 w-24">Amount</th>
                <th className="text-gray-400 font-medium text-center px-1 py-2 w-8"></th>
              </tr>
            </thead>
            <tbody>
              {effectiveLines.map((line, idx) => (
                <tr key={line.localId} className={`border-b border-gray-700/60 ${idx % 2 === 1 ? 'bg-gray-800/40' : ''}`}>
                  <td className="px-2 py-1 text-gray-600 text-center text-xs">{idx + 1}</td>
                  <td className="px-1 py-1 min-w-[180px] max-w-[240px]">
                    <SearchableSelect
                      options={accountOptions}
                      value={line.accountId}
                      onChange={(value) => {
                        const account = accounts.find((a) => a.Id === value);
                        updateLine(line.localId, { accountId: value, accountName: account?.FullyQualifiedName ?? '' });
                      }}
                      placeholder="Account…"
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[160px]">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 focus:border-cyan-500 focus:outline-none"
                      value={line.description}
                      onChange={(e) => updateLine(line.localId, { description: e.target.value })}
                      placeholder="Description…"
                      maxLength={4000}
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[120px] max-w-[160px]">
                    <SearchableSelect
                      options={classOptions}
                      value={line.classId}
                      onChange={(value) => updateLine(line.localId, { classId: value })}
                      placeholder="Class…"
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[120px] max-w-[160px]">
                    <SearchableSelect
                      options={taxCodeOptions}
                      value={line.taxCodeId}
                      onChange={(value) => updateLine(line.localId, { taxCodeId: value })}
                      placeholder="Tax Code…"
                    />
                  </td>
                  <td className="px-1 py-1 text-right w-24">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 text-right focus:border-cyan-500 focus:outline-none"
                      value={line.amount}
                      onChange={(e) => updateLine(line.localId, { amount: e.target.value })}
                      placeholder="0.00"
                      inputMode="decimal"
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <button
                      type="button"
                      onClick={() => removeLine(line.localId)}
                      className="text-gray-400 hover:text-red-400"
                      disabled={effectiveLines.length <= 1}
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="border-t border-gray-600 bg-gray-700/30 font-semibold">
                <td className="px-2 py-2 text-gray-500">{effectiveLines.length}</td>
                <td colSpan={4} className="px-2 py-2 text-gray-500">Total</td>
                <td className="px-2 py-2 text-right font-mono text-blue-300">${fmt(totalAmount)}</td>
                <td />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <button
        type="button"
        onClick={addLine}
        className="w-full text-xs text-gray-500 hover:text-gray-300 border border-dashed border-gray-700 hover:border-gray-500 py-1.5 rounded-lg transition-colors"
      >
        + Add Line
      </button>

      {duplicateWarning && (
        <ErrorCard
          variant="warning"
          message={duplicateWarning}
          onDismiss={() => setDuplicateWarning(null)}
          onRetry={handleForceSync}
        />
      )}
      {error && (
        <div className="bg-red-900/40 border border-red-700 text-red-300 text-xs rounded-lg px-3 py-2">
          {error}
        </div>
      )}
      {syncResult && (
        <div className="bg-green-900/40 border border-green-700 text-green-300 text-xs rounded-lg px-3 py-2 space-y-1.5">
          <div>✅ Vendor Credit created — <span className="font-mono">{syncResult.id}</span></div>
          {syncResult.docNumber && <div>Credit # {syncResult.docNumber}</div>}
          <div className="flex items-center gap-2">
            <button
              onClick={() => navigator.clipboard.writeText(syncResult.id).catch(() => {})}
              className="text-xs text-cyan-400 hover:text-cyan-300 border border-cyan-800 hover:border-cyan-600 px-2 py-0.5 rounded transition-colors"
            >
              Copy ID
            </button>
            <a
              href={`${status.environment === 'sandbox' ? 'https://app.sandbox.qbo.intuit.com' : 'https://app.qbo.intuit.com'}/app/vendorcredit?txnId=${syncResult.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs text-cyan-400 hover:underline"
            >
              View in QuickBooks ↗
            </a>
          </div>
        </div>
      )}

      <div className="flex gap-2">
        <button
          type="button"
          onClick={handleClearAll}
          className="px-3 py-2 text-xs text-red-400 border border-red-800 hover:bg-red-900/20 rounded-lg transition-colors"
        >
          Clear All
        </button>
        <button
          type="button"
          onClick={() => void handleSync()}
          disabled={syncing || !hasHeader || !allMapped || !hasAmount}
          className="flex-1 py-2.5 bg-green-600 hover:bg-green-500 disabled:bg-gray-700 disabled:text-gray-500 text-white text-sm font-bold rounded-lg transition-colors"
        >
          {syncing
            ? 'Syncing Vendor Credit…'
            : !hasHeader
              ? '⚠️ Vendor and AP account required'
              : !hasAmount
                ? '⚠️ Add credit amounts'
                : !allMapped
                  ? '⚠️ Assign all line accounts'
                  : '⚡ Sync Vendor Credit to QuickBooks'}
        </button>
      </div>
    </div>
  );
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { api, ApiError } from '../lib/api';
import { extractLineItems, getAutoFillSummary } from '../lib/column-extractor';
import { useLocations } from '../hooks/useLocations';
import { useQuickBooks } from '../hooks/useQuickBooks';
import { useQBContext } from '../contexts/QBContext';
import SearchableSelect from './SearchableSelect';
import SmartDatePicker from './SmartDatePicker';
import ErrorCard from './shared/ErrorCard';
import type { ExtractedLineItem, ScanData, ScanEntry, Mapping, Template } from '../../types';
import type { SelectOption } from './SearchableSelect';
import type { QBAccount } from '../types/qb';
import { decodeMapping } from '../lib/je-builder';
import { parseNumericValue } from '../lib/parse-numeric-value';

interface CheckLine {
  localId: string;
  accountId: string;
  accountName: string;
  description: string;
  classId: string;
  amount: string;
}

function newLine(overrides?: Partial<CheckLine>): CheckLine {
  return {
    localId: `line-${Date.now()}-${Math.random()}`,
    accountId: '',
    accountName: '',
    description: '',
    classId: '',
    amount: '',
    ...overrides,
  };
}

function toYMD(date: Date): string {
  return date.toISOString().split('T')[0]!;
}

function parseScanDate(raw: string | undefined): string | undefined {
  if (!raw) return undefined;
  const trimmed = raw.trim();
  if (!trimmed) return undefined;

  const textual = Date.parse(trimmed);
  if (!isNaN(textual)) {
    return toYMD(new Date(textual));
  }

  const slashMatch = trimmed.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (slashMatch) {
    const [, numA, numB, yearStr] = slashMatch;
    let year = yearStr.length === 2 ? 2000 + parseInt(yearStr, 10) : parseInt(yearStr, 10);
    const a = parseInt(numA, 10);
    const b = parseInt(numB, 10);

    if (a > 12) {
      return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
    }
    if (b > 12) {
      return `${year}-${String(a).padStart(2, '0')}-${String(b).padStart(2, '0')}`;
    }
    return `${year}-${String(b).padStart(2, '0')}-${String(a).padStart(2, '0')}`;
  }

  return undefined;
}

function fmt(amount: number): string {
  return amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

interface Props {
  jwt: string;
  scanData: ScanData | null;
  activeScanEntry?: ScanEntry | null;
  selectedLocationId: string;
  scanRecordId?: string | null;
  selectedTemplate?: Template | null;
}

export default function CheckPreviewForm({
  jwt,
  scanData,
  activeScanEntry,
  selectedLocationId,
  scanRecordId,
  selectedTemplate,
}: Props) {
  const { status, connect } = useQuickBooks(jwt);
  const { locations } = useLocations(jwt);
  const {
    accounts,
    classes,
    vendors,
    listsLoaded,
    listsLoading,
    listsError,
    syncAllLists,
  } = useQBContext();

  const today = toYMD(new Date());
  const [txnDate, setTxnDate] = useState(today);
  const [bankAccountRef, setBankAccountRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [payeeRef, setPayeeRef] = useState<{ value: string; name?: string }>({ value: '' });
  const [memo, setMemo] = useState('');
  const [docNumber, setDocNumber] = useState('');
  const [lines, setLines] = useState<CheckLine[]>([newLine(), newLine()]);
  const [savedMappings, setSavedMappings] = useState<Mapping[]>([]);
  const [mappingsLoaded, setMappingsLoaded] = useState(false);
  const [ruleTransformedLineItems, setRuleTransformedLineItems] = useState<Record<string, string>[] | null>(null);
  const [autoFillSummary, setAutoFillSummary] = useState<{ total: number; mapped: number; unmapped: number } | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ id: string; txnDate: string; docNumber?: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);

  const accountsRef = useRef(accounts);
  accountsRef.current = accounts;
  const userHasEditedLinesRef = useRef(false);

  const locId = selectedLocationId || locations[0]?.id || '';

  useEffect(() => {
    userHasEditedLinesRef.current = false;
  }, [activeScanEntry]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    if (!selectedTemplate?.columnMappings || !selectedTemplate?.id) return;
    if (!jwt || !locId) return;
    if (userHasEditedLinesRef.current) return;

    let cancelled = false;
    (async () => {
      try {
        const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
        if (cancelled) return;
        const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
        const extracted = extractLineItems({
          lineItems: itemsToExtract,
          columnMappings: selectedTemplate.columnMappings,
          productMappings,
          defaultPostingType: 'Debit',
        });
        if (cancelled) return;

        setLines(extracted.map((item) => newLine({
          accountId: item.accountId,
          accountName: item.accountName || accountsRef.current.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
          description: item.description,
          classId: item.classId ?? '',
          amount: item.amount.toFixed(2),
        })));
        setAutoFillSummary(getAutoFillSummary(extracted));
      } catch {
        // silent fallback
      }
    })();

    return () => { cancelled = true; };
  }, [activeScanEntry, selectedTemplate, jwt, locId, ruleTransformedLineItems]);

  useEffect(() => {
    if (!listsLoaded && !listsLoading && !listsError) {
      void syncAllLists();
    }
  }, [listsLoaded, listsLoading, listsError, syncAllLists]);

  useEffect(() => {
    if (!jwt || !locId) return;
    setMappingsLoaded(false);
    api.getMappings(jwt, locId)
      .then((mappings) => {
        setSavedMappings(mappings);
        setMappingsLoaded(true);
      })
      .catch((err) => {
        console.error('[Check Preview] Failed to load mappings:', err);
        setMappingsLoaded(true);
      });
  }, [jwt, locId]);

  useEffect(() => {
    if (!jwt || !locId || !activeScanEntry?.lineItems?.length) return;
    if (!selectedTemplate?.id) return;

    const apply = async () => {
      try {
        const rules = await api.getRules(jwt, locId, selectedTemplate?.id);
        const activeRules = rules.filter((r) => r.isActive);
        if (activeRules.length === 0) {
          setRuleTransformedLineItems(null);
          return;
        }

        const result = await api.applyRules(jwt, {
          lineItems: activeScanEntry.lineItems,
          rules: activeRules,
        });
        if (result.type === 'lineItems') {
          setRuleTransformedLineItems(result.data);
        }
      } catch (err) {
        console.error('[Check Preview] Failed to apply rules:', err);
      }
    };

    void apply();
  }, [jwt, locId, activeScanEntry, selectedTemplate?.id]);

  useEffect(() => {
    if (!scanData || !locId) return;
    const loc = locations.find((location) => location.id === locId);
    if (!loc) return;
    const memoTemplate = loc.memoTemplate;
    const docNumberTemplate = loc.docNumberTemplate;

    if (memoTemplate) {
      setMemo((prev) => prev || memoTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }

    if (docNumberTemplate) {
      setDocNumber((prev) => prev || docNumberTemplate.replace(/\{(\w+)\}/g, (match, field: string) => {
        const key = Object.keys(scanData).find((k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase());
        return key !== undefined ? String(scanData[key]) : match;
      }));
    }
  }, [scanData, locId, locations]);

  useEffect(() => {
    if (!selectedTemplate || selectedTemplate.transactionType !== 'CHEQUE') return;
    const defaults = selectedTemplate.defaults as Record<string, { value: string; name?: string } | null> | null;
    if (!defaults) return;

    if (defaults.bankAccountRef) setBankAccountRef(defaults.bankAccountRef);
    if (defaults.payeeRef) setPayeeRef(defaults.payeeRef);
    if (defaults.memo?.value) setMemo(defaults.memo.value);
    if (defaults.docNumber?.value) setDocNumber(defaults.docNumber.value);
  }, [selectedTemplate]);

  useEffect(() => {
    if (!activeScanEntry) return;
    if (activeScanEntry.source === 'pos') return;
    const h = activeScanEntry.header;
    if (!h || !Object.keys(h).length) return;

    setPayeeRef((prev) => {
      if (prev.value) return prev;
      const vendorName = (h.payeeName || h.vendor || '').trim();
      if (!vendorName) return prev;
      const lower = vendorName.toLowerCase();
      const match = vendors.find((v) => {
        if (v.DisplayName.toLowerCase() === lower) return true;
        if (v.CompanyName?.toLowerCase() === lower) return true;
        if (v.DisplayName.toLowerCase().includes(lower)) return true;
        if (v.CompanyName?.toLowerCase()?.includes(lower)) return true;
        if (lower.includes(v.DisplayName.toLowerCase())) return true;
        if (v.CompanyName && lower.includes(v.CompanyName.toLowerCase())) return true;
        return false;
      });
      if (match) return { value: match.Id, name: match.DisplayName };
      return prev;
    });

    setDocNumber((prev) => {
      if (prev) return prev;
      return (h.chequeNumber || '').trim() || prev;
    });

    const parsedDate = parseScanDate(h.date || h.chequeDate || h.invoiceDate);
    if (parsedDate) {
      setTxnDate((prev) => {
        if (prev && prev !== toYMD(new Date())) return prev;
        return parsedDate;
      });
    }

    if (h.memo) {
      setMemo((prev) => {
        if (prev) return prev;
        return String(h.memo);
      });
    }

    if (h.bankName && !bankAccountRef.value) {
      const bankName = String(h.bankName).toLowerCase();
      const match = accounts.find((a) => a.FullyQualifiedName.toLowerCase().includes(bankName));
      if (match) setBankAccountRef({ value: match.Id, name: match.FullyQualifiedName });
    }
  }, [activeScanEntry, vendors, accounts, bankAccountRef.value]);

  useEffect(() => {
    if (!mappingsLoaded) return;
    if (activeScanEntry?.source === 'image' || activeScanEntry?.source === 'pdf') return;
    const decoded = savedMappings.map(decodeMapping);
    const scanFields: Record<string, number> = activeScanEntry
      ? Object.fromEntries(
        Object.entries(activeScanEntry.lineItems?.[0] ?? {})
          .map(([key, value]) => [key, parseNumericValue(value)])
          .filter(([, v]) => v !== 0),
      ) as Record<string, number>
      : scanData ?? {};

    const checkLines = Object.entries(scanFields)
      .filter(([, amount]) => amount !== 0)
      .map(([field, amount]) => {
        const mapping = decoded.find((m) => m.sourceField === field);
        const accountId = mapping?.accountId ?? '';
        const accountName = accountsRef.current.find((a) => a.Id === accountId)?.FullyQualifiedName ?? '';
        return newLine({
          accountId,
          accountName,
          description: mapping?.description ?? field,
          classId: mapping?.classId ?? '',
          amount: Math.abs(amount).toFixed(2),
        });
      });

    if (checkLines.length > 0) {
      setLines(checkLines);
    }
  }, [activeScanEntry, scanData, savedMappings, mappingsLoaded, accountsRef]);

  const payeeOptions = useMemo(() =>
    vendors
      .filter((vendor) => vendor.Active)
      .map((vendor) => ({ value: vendor.Id, label: vendor.DisplayName, subtitle: vendor.CompanyName ?? undefined })),
    [vendors],
  );

  const bankAccountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .filter((account) =>
        account.AccountType === 'Asset' &&
        (account.AccountSubType?.includes('Bank') ||
          account.AccountSubType?.includes('Checking') ||
          account.AccountSubType?.includes('Savings'))
      )
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType })),
    [accounts],
  );

  const accountOptions = useMemo(() =>
    accounts
      .filter((account) => account.Active)
      .map((account) => ({ value: account.Id, label: account.FullyQualifiedName, subtitle: account.AccountSubType, group: account.Classification || account.AccountType })),
    [accounts],
  );

  const classOptions = useMemo(() =>
    classes.filter((item) => item.Active).map((item) => ({ value: item.Id, label: item.FullyQualifiedName })),
    [classes],
  );

  const updateLine = (localId: string, patch: Partial<CheckLine>) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.map((line) => (line.localId === localId ? { ...line, ...patch } : line)));
  };

  const removeLine = (localId: string) => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => prev.filter((line) => line.localId !== localId));
  };

  const addLine = () => {
    userHasEditedLinesRef.current = true;
    setLines((prev) => [...prev, newLine()]);
  };

  const effectiveLines = lines;
  const totalAmount = effectiveLines.reduce((sum, line) => sum + (parseFloat(line.amount) || 0), 0);
  const unmappedCount = effectiveLines.filter((line) => parseFloat(line.amount) > 0 && !line.accountId).length;
  const hasAmount = effectiveLines.some((line) => parseFloat(line.amount) > 0);
  const allMapped = unmappedCount === 0 && hasAmount;
  const hasHeader = Boolean(bankAccountRef.value && payeeRef.value);

  const handleClearAll = () => {
    setTxnDate(today);
    setBankAccountRef({ value: '' });
    setPayeeRef({ value: '' });
    setMemo('');
    setDocNumber('');
    setLines([newLine(), newLine()]);
    userHasEditedLinesRef.current = false;
    setError(null);
    setSyncResult(null);
    setAutoFillSummary(null);
    setRuleTransformedLineItems(null);
  };

  const handleAutoFill = useCallback(async () => {
    if (!activeScanEntry?.lineItems?.length) {
      setError('No scan line items available to auto-fill');
      return;
    }
    if (!selectedTemplate?.columnMappings) {
      setError('Template column mappings are required for auto-fill');
      return;
    }
    if (!selectedTemplate?.id) return;

    setError(null);

    try {
      const productMappings = await api.getProductMappings(jwt, selectedTemplate.id);
      const itemsToExtract = ruleTransformedLineItems ?? activeScanEntry.lineItems ?? [];
      const extracted = extractLineItems({
        lineItems: itemsToExtract,
        columnMappings: selectedTemplate.columnMappings,
        productMappings,
        defaultPostingType: 'Debit',
      });

      const checkLines = extracted.map((item) => newLine({
        accountId: item.accountId,
        accountName: item.accountName || accounts.find((a) => a.Id === item.accountId)?.FullyQualifiedName || '',
        description: item.description,
        classId: item.classId ?? '',
        amount: item.amount.toFixed(2),
      }));

      setLines(checkLines);
      setAutoFillSummary(getAutoFillSummary(extracted));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Auto-fill failed');
    }
  }, [activeScanEntry, accounts, jwt, selectedTemplate, ruleTransformedLineItems]);

  const handleSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const checkLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
        }));

      const result = await api.createCheque(
        jwt,
        txnDate,
        bankAccountRef,
        payeeRef,
        totalAmount,
        checkLines,
        scanRecordId ?? undefined,
        memo || undefined,
        docNumber || undefined,
      ) as { chequeId: string; txnDate: string; docNumber?: string };

      setSyncResult({ id: result.chequeId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Check sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, bankAccountRef, docNumber, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, totalAmount, txnDate, payeeRef]);

  const handleForceSync = useCallback(async () => {
    if (!hasHeader || !allMapped || !hasAmount) return;
    setSyncing(true);
    setError(null);
    setDuplicateWarning(null);
    setSyncResult(null);

    try {
      const checkLines = effectiveLines
        .filter((line) => parseFloat(line.amount) > 0)
        .map((line) => ({
          amount: parseFloat(line.amount),
          accountRef: { value: line.accountId, name: line.accountName || undefined },
          description: line.description || undefined,
          classRef: line.classId ? { value: line.classId } : undefined,
        }));

      const result = await api.createCheque(
        jwt,
        txnDate,
        bankAccountRef,
        payeeRef,
        totalAmount,
        checkLines,
        scanRecordId ?? undefined,
        memo || undefined,
        docNumber || undefined,
        true,
      ) as { chequeId: string; txnDate: string; docNumber?: string };

      setSyncResult({ id: result.chequeId, txnDate: result.txnDate, docNumber: result.docNumber });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Check sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [allMapped, bankAccountRef, docNumber, effectiveLines, hasAmount, hasHeader, jwt, memo, scanRecordId, totalAmount, txnDate, payeeRef]);

  if (!status.connected) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center px-4">
        <div className="text-4xl mb-3">🔗</div>
        <p className="text-gray-400 text-sm mb-1">QuickBooks not connected</p>
        <p className="text-gray-600 text-xs mb-4">Connect QuickBooks in Settings to sync checks</p>
        <button onClick={connect} className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white px-4 py-2 rounded-lg">
          Connect QuickBooks
        </button>
      </div>
    );
  }

  return (
    <div className="p-3 flex flex-col gap-3">
      <div className="flex items-center gap-2 text-xs px-3 py-1.5 bg-green-900/20 border border-green-800 rounded-lg">
        <span className="text-green-400">✅ QB Connected</span>
        <span className="text-gray-600 truncate">{status.realmId}</span>
        <button
          onClick={() => void syncAllLists()}
          disabled={listsLoading}
          className="ml-auto text-gray-500 hover:text-gray-300 transition-colors"
          title="Refresh QB lists"
        >
          {listsLoading ? '…' : '↻'}
        </button>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 grid grid-cols-2 gap-3">
        <div>
          <div className="text-xs text-gray-500 mb-1">Transaction Date</div>
          <SmartDatePicker value={txnDate} onChange={setTxnDate} />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">Bank Account</div>
          <SearchableSelect
            options={bankAccountOptions}
            value={bankAccountRef.value}
            onChange={(value) => {
              const selected = accounts.find((a) => a.Id === value);
              setBankAccountRef({ value, name: selected?.FullyQualifiedName });
            }}
            placeholder="Select bank account…"
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Payee</div>
          <SearchableSelect
            options={payeeOptions}
            value={payeeRef.value}
            onChange={(value) => {
              const selected = vendors.find((v) => v.Id === value);
              setPayeeRef({ value, name: selected?.DisplayName });
            }}
            placeholder="Select payee/vendor…"
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Check # / Doc Number</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={docNumber}
            onChange={(e) => setDocNumber(e.target.value)}
            placeholder="Optional check number"
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Memo</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={memo}
            onChange={(e) => setMemo(e.target.value)}
            placeholder="Optional memo"
          />
        </div>
      </div>

      <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
        <div className="flex flex-col gap-2 px-3 py-3 border-b border-gray-700/60 sm:flex-row sm:items-center sm:justify-between">
          <button
            type="button"
            onClick={() => void handleAutoFill()}
            disabled={!activeScanEntry?.lineItems?.length || !selectedTemplate?.columnMappings}
            className="text-xs bg-cyan-700 hover:bg-cyan-600 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded px-3 py-1.5"
          >
            Auto-fill from Scan
          </button>
          {autoFillSummary ? (
            <div className="text-xs text-gray-300">
              {autoFillSummary.total} items: {autoFillSummary.mapped} mapped, {autoFillSummary.unmapped} unmapped
            </div>
          ) : null}
        </div>
        <div className="overflow-x-auto overflow-y-auto max-h-[320px]">
          <table className="w-full text-xs border-collapse min-w-[680px]">
            <thead>
              <tr className="border-b border-gray-700 bg-gray-700/50">
                <th className="text-gray-400 font-medium text-left px-2 py-2 w-8">#</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[180px]">Account</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[160px]">Description</th>
                <th className="text-gray-400 font-medium text-left px-2 py-2 min-w-[120px]">Class</th>
                <th className="text-gray-400 font-medium text-right px-2 py-2 w-24">Amount</th>
                <th className="text-gray-400 font-medium text-center px-1 py-2 w-8"></th>
              </tr>
            </thead>
            <tbody>
              {effectiveLines.map((line, idx) => (
                <tr key={line.localId} className={`border-b border-gray-700/60 ${idx % 2 === 1 ? 'bg-gray-800/40' : ''}`}>
                  <td className="px-2 py-1 text-gray-600 text-center text-xs">{idx + 1}</td>
                  <td className="px-1 py-1 min-w-[180px] max-w-[240px]">
                    <SearchableSelect
                      options={accountOptions}
                      value={line.accountId}
                      onChange={(value) => {
                        const account = accounts.find((a) => a.Id === value);
                        updateLine(line.localId, { accountId: value, accountName: account?.FullyQualifiedName ?? '' });
                      }}
                      placeholder="Account…"
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[160px]">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 focus:border-cyan-500 focus:outline-none"
                      value={line.description}
                      onChange={(e) => updateLine(line.localId, { description: e.target.value })}
                      placeholder="Description…"
                      maxLength={4000}
                    />
                  </td>
                  <td className="px-1 py-1 min-w-[120px] max-w-[160px]">
                    <SearchableSelect
                      options={classOptions}
                      value={line.classId}
                      onChange={(value) => updateLine(line.localId, { classId: value })}
                      placeholder="Class…"
                    />
                  </td>
                  <td className="px-1 py-1 text-right w-24">
                    <input
                      className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 text-right focus:border-cyan-500 focus:outline-none"
                      value={line.amount}
                      onChange={(e) => updateLine(line.localId, { amount: e.target.value })}
                      placeholder="0.00"
                      inputMode="decimal"
                    />
                  </td>
                  <td className="px-1 py-1 text-center">
                    <button
                      type="button"
                      onClick={() => removeLine(line.localId)}
                      className="text-gray-400 hover:text-red-400"
                      disabled={effectiveLines.length <= 1}
                    >
                      ✕
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className="border-t border-gray-600 bg-gray-700/30 font-semibold">
                <td className="px-2 py-2 text-gray-500">{effectiveLines.length}</td>
                <td colSpan={3} className="px-2 py-2 text-gray-500">Total</td>
                <td className="px-2 py-2 text-right font-mono text-blue-300">${fmt(totalAmount)}</td>
                <td />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      <button
        type="button"
        onClick={addLine}
        className="w-full text-xs text-gray-500 hover:text-gray-300 border border-dashed border-gray-700 hover:border-gray-500 py-1.5 rounded-lg transition-colors"
      >
        + Add Line
      </button>

      {duplicateWarning && (
        <ErrorCard
          variant="warning"
          message={duplicateWarning}
          onDismiss={() => setDuplicateWarning(null)}
          onRetry={handleForceSync}
        />
      )}
      {error && (
        <div className="bg-red-900/40 border border-red-700 text-red-300 text-xs rounded-lg px-3 py-2">
          {error}
        </div>
      )}
      {syncResult && (
        <div className="bg-green-900/40 border border-green-700 text-green-300 text-xs rounded-lg px-3 py-2 space-y-1.5">
          <div>✅ Check created — <span className="font-mono">{syncResult.id}</span></div>
          {syncResult.docNumber && <div>Check # {syncResult.docNumber}</div>}
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => navigator.clipboard.writeText(syncResult.id).catch(() => {})}
              className="text-xs text-cyan-400 hover:text-cyan-300 border border-cyan-800 hover:border-cyan-600 px-2 py-0.5 rounded transition-colors"
            >
              Copy ID
            </button>
            <a
              href={`${status.environment === 'sandbox' ? 'https://app.sandbox.qbo.intuit.com' : 'https://app.qbo.intuit.com'}/app/expense?txnId=${syncResult.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs text-cyan-400 hover:underline"
            >
              View in QuickBooks ↗
            </a>
          </div>
        </div>
      )}

      <div className="flex gap-2">
        <button
          type="button"
          onClick={handleClearAll}
          className="px-3 py-2 text-xs text-red-400 border border-red-800 hover:bg-red-900/20 rounded-lg transition-colors"
        >
          Clear All
        </button>
        <button
          type="button"
          onClick={() => void handleSync()}
          disabled={syncing || !hasHeader || !allMapped || !hasAmount}
          className="flex-1 py-2.5 bg-green-600 hover:bg-green-500 disabled:bg-gray-700 disabled:text-gray-500 text-white text-sm font-bold rounded-lg transition-colors"
        >
          {syncing
            ? 'Syncing Check…'
            : !hasHeader
              ? '⚠️ Bank and payee required'
              : !hasAmount
                ? '⚠️ Add check amounts'
                : !allMapped
                  ? '⚠️ Assign all line accounts'
                  : '⚡ Sync Check to QuickBooks'}
        </button>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { api, ApiError } from '../lib/api';
import { useLocations } from '../hooks/useLocations';
import { useQuickBooks } from '../hooks/useQuickBooks';
import { useQBContext } from '../contexts/QBContext';
import SearchableSelect from './SearchableSelect';
import SmartDatePicker from './SmartDatePicker';
import ErrorCard from './shared/ErrorCard';
import type { ScanData, ScanEntry, Mapping } from '../../types';
import type { SelectOption } from './SearchableSelect';
import type { QBAccount } from '../types/qb';
import { guessPostingType, decodeMapping } from '../lib/je-builder';
import { parseNumericValue } from '../lib/parse-numeric-value';

// ── Types ─────────────────────────────────────────────────────────────────────

interface LineItem {
  localId: string;
  accountId: string;
  accountName: string;
  entityVal: string; // "customer:ID" | "vendor:ID" | "employee:ID" | ""
  description: string;
  classId: string;
  taxCodeId: string;
  debit: string;
  credit: string;
  keepSeparate: boolean;
}

type ColKey = 'account' | 'name' | 'description' | 'class' | 'taxCode' | 'debit' | 'credit';

const ALL_COLUMNS: { key: ColKey; label: string }[] = [
  { key: 'account', label: 'Account' },
  { key: 'name', label: 'Name' },
  { key: 'description', label: 'Description' },
  { key: 'class', label: 'Class' },
  { key: 'taxCode', label: 'Tax Code' },
  { key: 'debit', label: 'Debit' },
  { key: 'credit', label: 'Credit' },
];

const LS_COL_KEY = 'nest_je_col_vis';

function loadColVis(): Record<ColKey, boolean> {
  try {
    const raw = localStorage.getItem(LS_COL_KEY);
    if (raw) return JSON.parse(raw) as Record<ColKey, boolean>;
  } catch { /* ignore */ }
  return { account: true, name: true, description: true, class: true, taxCode: true, debit: true, credit: true };
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function fmt(n: number): string {
  return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function newLine(overrides?: Partial<LineItem>): LineItem {
  return {
    localId: `line-${Date.now()}-${Math.random()}`,
    accountId: '',
    accountName: '',
    entityVal: '',
    description: '',
    classId: '',
    taxCodeId: '',
    debit: '',
    credit: '',
    keepSeparate: false,
    ...overrides,
  };
}

function toYMD(d: Date): string {
  return d.toISOString().split('T')[0]!;
}

function resolveMemoTemplate(template: string, data: ScanData | null): string {
  if (!template || !data) return '';
  return template.replace(/\{(\w+)\}/g, (match, field: string) => {
    const key = Object.keys(data).find(
      (k) => k.toLowerCase().replace(/\s+/g, '_') === field.toLowerCase(),
    );
    return key !== undefined ? String(data[key]) : match;
  });
}

// ── Main Component ────────────────────────────────────────────────────────────

interface Props {
  jwt: string;
  scanData: ScanData | null;
  scanEntries: ScanEntry[];
  activeScanEntry?: ScanEntry | null;
  activeScanEntryId: string | null;
  onActiveScanEntryIdChange: (id: string) => void;
  selectedLocationId: string;
  scanRecordId?: string | null;
}

export default function JournalEntryPreview({ jwt, scanData, scanEntries, activeScanEntry, activeScanEntryId, onActiveScanEntryIdChange, selectedLocationId, scanRecordId }: Props) {
  const { status, connect } = useQuickBooks(jwt);
  const { locations } = useLocations(jwt);
  const {
    accounts, classes, employees, vendors, customers, taxCodes,
    listsLoaded, listsLoading, listsError, syncAllLists,
  } = useQBContext();

  const today = toYMD(new Date());
  const [txnDate, setTxnDate] = useState(today);
  const [docNumber, setDocNumber] = useState('');
  const [privateNote, setPrivateNote] = useState('');
  const [isAdjusting, setIsAdjusting] = useState(false);
  const [lines, setLines] = useState<LineItem[]>([newLine(), newLine()]);
  const [colVis, setColVis] = useState<Record<ColKey, boolean>>(loadColVis);
  const [showColMenu, setShowColMenu] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ id: string; txnDate: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [duplicateWarning, setDuplicateWarning] = useState<string | null>(null);
  const [savedMappings, setSavedMappings] = useState<Mapping[]>([]);
  const [mappingsLoaded, setMappingsLoaded] = useState(false);
  const [ruleTransformedData, setRuleTransformedData] = useState<Record<string, number> | null>(null);
  const [ruleTransformedLineItems, setRuleTransformedLineItems] = useState<Record<string, string>[] | null>(null);
  const rulesAppliedRef = useRef(false);
  const [consolidate, setConsolidate] = useState(false);

  // Keep a stable ref to accounts to avoid re-render loops in the scan effect
  const accountsRef = useRef(accounts);
  accountsRef.current = accounts;

  // Track which ScanEntry has been auto-populated (prevent overwrite on re-render)
  const autoPopulatedForRef = useRef<string | null>(null);

  // Persist column visibility
  useEffect(() => {
    localStorage.setItem(LS_COL_KEY, JSON.stringify(colVis));
  }, [colVis]);

  // Load QB lists on mount
  useEffect(() => {
    if (!listsLoaded && !listsLoading && !listsError) void syncAllLists();
  }, [listsLoaded, listsLoading, listsError, syncAllLists]);

  const locId = selectedLocationId || locations[0]?.id || '';

  // Load saved mappings for this location
  useEffect(() => {
    if (!jwt || !locId) return;
    setMappingsLoaded(false);
    api.getMappings(jwt, locId)
      .then((mappings) => {
        setSavedMappings(mappings);
        setMappingsLoaded(true);
      })
      .catch((err) => {
        console.error('[JE Preview] Failed to load mappings:', err);
        setMappingsLoaded(true);
      });
  }, [jwt, locId]);

  // Apply memo/docNumber templates from location data when scan data loads
  useEffect(() => {
    if (!scanData || !locId) return;
    const loc = locations.find(l => l.id === locId);
    if (!loc) return;
    if (loc.memoTemplate) setPrivateNote(resolveMemoTemplate(loc.memoTemplate, scanData));
    if (loc.docNumberTemplate) setDocNumber(resolveMemoTemplate(loc.docNumberTemplate, scanData));
  }, [scanData, locId, locations]);

  useEffect(() => {
    rulesAppliedRef.current = false;
    setRuleTransformedData(null);
    setRuleTransformedLineItems(null);
  }, [activeScanEntryId, scanData]);

  // Fetch and apply active rules to current scan data or line item rows
  useEffect(() => {
    if (rulesAppliedRef.current || !jwt || !locId) return;
    rulesAppliedRef.current = true;

    const applyRulesToScan = async () => {
      try {
        const rules = await api.getRules(jwt, locId);
        const activeRules = rules.filter((r) => r.isActive);
        if (activeRules.length === 0) return;

        if (activeScanEntry?.lineItems?.length) {
          const result = await api.applyRules(jwt, {
            lineItems: activeScanEntry.lineItems,
            rules: activeRules,
          });
          if (result.type === 'lineItems') {
            setRuleTransformedLineItems(result.data);
          }
          return;
        }

        if (scanData) {
          const result = await api.applyRules(jwt, {
            scanData,
            rules: activeRules,
          });
          if (result.type === 'flat') {
            setRuleTransformedData(result.data);
          }
        }
      } catch (err) {
        console.error('[JE Preview] Failed to apply rules:', err);
      }
    };

    void applyRulesToScan();
  }, [jwt, locId, activeScanEntry, scanData]);

  // Auto-populate header fields from non-POS ScanEntry using mapping-based detection
  useEffect(() => {
    if (!activeScanEntry || activeScanEntry.source === 'pos' || !mappingsLoaded) return;
    if (autoPopulatedForRef.current === activeScanEntry.id) return;

    const header = activeScanEntry.header;
    if (!header || Object.keys(header).length === 0) return;

    const shouldPopulateTxnDate = txnDate === today;
    const shouldPopulatePrivateNote = privateNote.trim() === '';
    const shouldPopulateDocNumber = docNumber.trim() === '';

    // Detect date field via mapping sourceField matching date pattern
    const dateMapping = savedMappings.find(m =>
      /date|txn/i.test(m.sourceField) && Object.prototype.hasOwnProperty.call(header, m.sourceField)
    );
    if (dateMapping && header[dateMapping.sourceField] && shouldPopulateTxnDate) {
      const parsed = new Date(header[dateMapping.sourceField]);
      if (!isNaN(parsed.getTime())) {
        setTxnDate(parsed.toISOString().split('T')[0]);
      }
    }

    // Detect memo/description field
    const memoMapping = savedMappings.find(m =>
      /memo|description|note/i.test(m.sourceField) && Object.prototype.hasOwnProperty.call(header, m.sourceField)
    );
    if (memoMapping && header[memoMapping.sourceField] && shouldPopulatePrivateNote) {
      setPrivateNote(header[memoMapping.sourceField]);
    } else if (shouldPopulatePrivateNote) {
      const vendorMapping = savedMappings.find(m =>
        /vendor|name|payee/i.test(m.sourceField) && Object.prototype.hasOwnProperty.call(header, m.sourceField)
      );
      if (vendorMapping && header[vendorMapping.sourceField]) {
        setPrivateNote(header[vendorMapping.sourceField]);
      }
    }

    // Detect doc/reference field
    const docMapping = savedMappings.find(m =>
      /doc|number|reference|invoice\s*no/i.test(m.sourceField) && Object.prototype.hasOwnProperty.call(header, m.sourceField)
    );
    if (docMapping && header[docMapping.sourceField] && shouldPopulateDocNumber) {
      setDocNumber(header[docMapping.sourceField]);
    }

    autoPopulatedForRef.current = activeScanEntry.id;
  }, [activeScanEntry, savedMappings, mappingsLoaded, txnDate, privateNote, docNumber, today]);

  // Build lines from the current active scan entry when available
  useEffect(() => {
    if (!activeScanEntry || !mappingsLoaded) return;
    const decoded = savedMappings.map(decodeMapping);
    const currentLineItem = (ruleTransformedLineItems?.[0] ?? activeScanEntry.lineItems?.[0]) ?? {};
    const scanLines: LineItem[] = Object.entries(currentLineItem)
      .map(([field, rawValue]) => ({ field, amount: parseNumericValue(rawValue) }))
      .filter((entry) => !Number.isNaN(entry.amount) && entry.amount !== 0)
      .map(({ field, amount }) => {
        const mapping = decoded.find((m) => m.sourceField === field);
        const rawSide = mapping
          ? mapping.postingType.toLowerCase() as 'debit' | 'credit'
          : guessPostingType(field);
        const side = amount < 0
          ? (rawSide === 'debit' ? 'credit' : 'debit')
          : rawSide;
        const accountName = mapping
          ? (accountsRef.current.find((a) => a.Id === mapping.accountId)?.FullyQualifiedName ?? '')
          : '';
        return newLine({
          description: mapping?.description ?? field,
          accountId: mapping?.accountId ?? '',
          accountName,
          classId: mapping?.classId ?? '',
          keepSeparate: mapping?.keepSeparate ?? false,
          debit: side === 'debit' ? Math.abs(amount).toFixed(2) : '',
          credit: side === 'credit' ? Math.abs(amount).toFixed(2) : '',
        });
      });
    if (scanLines.length > 0) setLines(scanLines);
  }, [activeScanEntry, savedMappings, mappingsLoaded]);

  // Build lines from scan data, applying saved mappings
  useEffect(() => {
    if (activeScanEntry) return;
    const data = ruleTransformedData ?? scanData;
    if (!data || !mappingsLoaded) return;
    const decoded = savedMappings.map(decodeMapping);
    const scanLines: LineItem[] = Object.entries(data)
      .filter(([, v]) => v !== 0)
      .map(([field, amount]) => {
        const mapping = decoded.find((m) => m.sourceField === field);
        const rawSide = mapping
          ? mapping.postingType.toLowerCase() as 'debit' | 'credit'
          : guessPostingType(field);
        // Negative amount flips the posting side: a negative Credit is a Debit, and vice versa
        const side = amount < 0
          ? (rawSide === 'debit' ? 'credit' : 'debit')
          : rawSide;
        const accountName = mapping
          ? (accountsRef.current.find((a) => a.Id === mapping.accountId)?.FullyQualifiedName ?? '')
          : '';
        return newLine({
          description: mapping?.description ?? field,
          accountId: mapping?.accountId ?? '',
          accountName,
          classId: mapping?.classId ?? '',
          keepSeparate: mapping?.keepSeparate ?? false,
          debit: side === 'debit' ? Math.abs(amount).toFixed(2) : '',
          credit: side === 'credit' ? Math.abs(amount).toFixed(2) : '',
        });
      });
    if (scanLines.length > 0) setLines(scanLines);
  }, [scanData, savedMappings, mappingsLoaded]); // NOTE: no `accounts` dep — uses accountsRef

  // Account options grouped by classification
  const accountOptions = useMemo((): SelectOption[] =>
    accounts
      .filter((a) => a.Active)
      .map((a) => ({
        value: a.Id,
        label: a.FullyQualifiedName,
        subtitle: a.AccountSubType,
        group: a.Classification || a.AccountType,
      }))
      .sort((a, b) => (a.group ?? '').localeCompare(b.group ?? '') || a.label.localeCompare(b.label)),
    [accounts],
  );

  const entityOptions = useMemo((): SelectOption[] => [
    ...customers.filter((c) => c.Active).map((c) => ({
      value: `customer:${c.Id}`,
      label: c.DisplayName,
      subtitle: c.CompanyName ?? undefined,
      group: 'Customers',
    })),
    ...vendors.filter((v) => v.Active).map((v) => ({
      value: `vendor:${v.Id}`,
      label: v.DisplayName,
      subtitle: v.CompanyName ?? undefined,
      group: 'Vendors',
    })),
    ...employees.filter((e) => e.Active).map((e) => ({
      value: `employee:${e.Id}`,
      label: e.DisplayName,
      group: 'Employees',
    })),
  ], [customers, vendors, employees]);

  const classOptions = useMemo((): SelectOption[] =>
    classes.filter((c) => c.Active).map((c) => ({ value: c.Id, label: c.FullyQualifiedName })),
    [classes],
  );

  const taxCodeOptions = useMemo((): SelectOption[] =>
    taxCodes.filter((t) => t.Active).map((t) => ({ value: t.Id, label: t.Name, subtitle: t.Description })),
    [taxCodes],
  );

  const updateLine = (localId: string, patch: Partial<LineItem>) =>
    setLines((prev) => prev.map((l) => (l.localId === localId ? { ...l, ...patch } : l)));

  const removeLine = (localId: string) =>
    setLines((prev) => prev.filter((l) => l.localId !== localId));

  // Consolidate lines that share the same accountId + side + classId
  const consolidateLines = useCallback((rawLines: LineItem[]): LineItem[] => {
    const groups: Record<string, LineItem[]> = {};
    const separate: LineItem[] = [];

    rawLines.forEach((line) => {
      if (line.keepSeparate || !line.accountId) {
        separate.push(line);
        return;
      }
      const debitAmt = parseFloat(line.debit) || 0;
      const side = debitAmt > 0 ? 'debit' : 'credit';
      const key = `${line.accountId}|${side}|${line.classId}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(line);
    });

    const merged: LineItem[] = Object.values(groups).map((group) => {
      if (group.length === 1) return group[0];
      const totalDebit = group.reduce((s, l) => s + (parseFloat(l.debit) || 0), 0);
      const totalCredit = group.reduce((s, l) => s + (parseFloat(l.credit) || 0), 0);
      const descriptions = group.map((l) => l.description).filter(Boolean);
      return newLine({
        accountId: group[0].accountId,
        accountName: group[0].accountName,
        classId: group[0].classId,
        description: descriptions.length <= 3
          ? descriptions.join(' + ')
          : `${descriptions.slice(0, 3).join(' + ')} +${descriptions.length - 3} more`,
        keepSeparate: false,
        debit: totalDebit ? totalDebit.toFixed(2) : '',
        credit: totalCredit ? totalCredit.toFixed(2) : '',
      });
    });

    return [...separate, ...merged];
  }, []);

  // Auto-balance: if rounding caused a tiny imbalance (≤ $0.02), adjust the largest line
  const rawDisplayLines = consolidate ? consolidateLines(lines) : lines;
  const rawTotalDebits = rawDisplayLines.reduce((s, l) => s + (parseFloat(l.debit) || 0), 0);
  const rawTotalCredits = rawDisplayLines.reduce((s, l) => s + (parseFloat(l.credit) || 0), 0);
  const rawDiff = rawTotalDebits - rawTotalCredits;

  let autoBalancedDisplayLines = rawDisplayLines;
  let autoBalancedThisRender: { amount: number; lineId: string } | null = null;

  if (Math.abs(rawDiff) > 0.001 && Math.abs(rawDiff) <= 0.02) {
    const shortSide = rawDiff > 0 ? 'credit' : 'debit';
    const candidates = rawDisplayLines.filter((l) => {
      const val = parseFloat(shortSide === 'debit' ? l.debit : l.credit) || 0;
      return val > 0;
    });
    if (candidates.length > 0) {
      const largest = candidates.reduce((best, l) => {
        const val = parseFloat(shortSide === 'debit' ? l.debit : l.credit) || 0;
        const bestVal = parseFloat(shortSide === 'debit' ? best.debit : best.credit) || 0;
        return val > bestVal ? l : best;
      });
      const adjustment = Math.abs(rawDiff);
      autoBalancedDisplayLines = rawDisplayLines.map((l) => {
        if (l.localId !== largest.localId) return l;
        if (shortSide === 'debit') {
          return { ...l, debit: ((parseFloat(l.debit) || 0) + adjustment).toFixed(2) };
        } else {
          return { ...l, credit: ((parseFloat(l.credit) || 0) + adjustment).toFixed(2) };
        }
      });
      autoBalancedThisRender = { amount: adjustment, lineId: largest.localId };
    }
  }

  const autoBalanced = autoBalancedThisRender;
  const effectiveDisplayLines = autoBalancedDisplayLines;

  const totalDebits = effectiveDisplayLines.reduce((s, l) => s + (parseFloat(l.debit) || 0), 0);
  const totalCredits = effectiveDisplayLines.reduce((s, l) => s + (parseFloat(l.credit) || 0), 0);
  const diff = totalDebits - totalCredits;
  const isBalanced = Math.abs(diff) < 0.01;

  const unmappedCount = effectiveDisplayLines.filter((l) => !l.accountId).length;
  const allMapped = unmappedCount === 0;

  const handleClearAll = () => {
    setLines([newLine(), newLine()]);
    setDocNumber('');
    setPrivateNote('');
    setIsAdjusting(false);
    setError(null);
    setSyncResult(null);
  };

  const handleSync = useCallback(async () => {
    if (!isBalanced) return;
    setSyncing(true);
    setError(null);
    setSyncResult(null);
    try {
      const jeLines = effectiveDisplayLines
        .filter((l) => parseFloat(l.debit) > 0 || parseFloat(l.credit) > 0)
        .flatMap((l) => {
          const debitAmt = parseFloat(l.debit) || 0;
          const creditAmt = parseFloat(l.credit) || 0;
          let entityRef: { value: string; name?: string; type?: string } | undefined;
          if (l.entityVal) {
            const parts = l.entityVal.split(':');
            const eType = parts[0];
            const eId = parts[1];
            const opt = entityOptions.find((o) => o.value === l.entityVal);
            if (eId) entityRef = {
              value: eId,
              name: opt?.label,
              type: eType === 'vendor' ? 'Vendor' : eType === 'employee' ? 'Employee' : 'Customer',
            };
          }
          const items = [];
          if (debitAmt > 0) {
            items.push({
              amount: debitAmt,
              postingType: 'Debit',
              accountRef: { value: l.accountId, name: l.accountName },
              description: l.description || undefined,
              classRef: l.classId ? { value: l.classId } : undefined,
              entityRef,
            });
          }
          if (creditAmt > 0) {
            items.push({
              amount: creditAmt,
              postingType: 'Credit',
              accountRef: { value: l.accountId, name: l.accountName },
              description: l.description || undefined,
              classRef: l.classId ? { value: l.classId } : undefined,
              entityRef,
            });
          }
          return items;
        });

      const result = await api.createJournalEntry(
        jwt,
        txnDate,
        jeLines,
        scanRecordId ?? undefined,
        privateNote || `Nest sync — ${txnDate} — ${locations[0]?.name ?? ''}`,
        docNumber || undefined,
      ) as { journalEntryId: string; txnDate: string };

      setSyncResult({ id: result.journalEntryId, txnDate: result.txnDate });
    } catch (err) {
      if (err instanceof ApiError && err.status === 409) {
        setDuplicateWarning(err.payload?.error ?? err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Sync failed');
      }
    } finally {
      setSyncing(false);
    }
  }, [jwt, effectiveDisplayLines, txnDate, docNumber, privateNote, locations, entityOptions, isBalanced, consolidate]);

  if (!status.connected) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-center px-4">
        <div className="text-4xl mb-3">🔗</div>
        <p className="text-gray-400 text-sm mb-1">QuickBooks not connected</p>
        <p className="text-gray-600 text-xs mb-4">Connect QuickBooks in Settings to sync journal entries</p>
        <button onClick={connect} className="text-xs bg-cyan-700 hover:bg-cyan-600 text-white px-4 py-2 rounded-lg">
          Connect QuickBooks
        </button>
      </div>
    );
  }

  return (
    <div className="p-3 flex flex-col gap-3">
      {/* QB Status */}
      <div className="flex items-center gap-2 text-xs px-3 py-1.5 bg-green-900/20 border border-green-800 rounded-lg">
        <span className="text-green-400">✅ QB Connected</span>
        <span className="text-gray-600 truncate">{status.realmId}</span>
        {isAdjusting && (
          <span className="ml-1 px-1.5 py-0.5 bg-yellow-900/40 border border-yellow-700 text-yellow-400 rounded text-xs">
            Adjusting Entry
          </span>
        )}
        <button
          onClick={() => void syncAllLists()}
          disabled={listsLoading}
          className="ml-auto text-gray-500 hover:text-gray-300 transition-colors"
          title="Refresh QB lists"
        >
          {listsLoading ? '…' : '↻'}
        </button>
      </div>

      {scanEntries.length > 1 && activeScanEntry && (
        <div className="flex items-center justify-between px-3 py-2 bg-gray-800/50 border border-gray-700 rounded-lg">
          <button
            type="button"
            onClick={() => {
              const idx = scanEntries.findIndex((e) => e.id === activeScanEntryId);
              if (idx > 0) onActiveScanEntryIdChange(scanEntries[idx - 1].id);
            }}
            disabled={scanEntries.findIndex((e) => e.id === activeScanEntryId) <= 0}
            className="px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
          >
            ← Prev Row
          </button>
          <span className="text-xs text-gray-300 font-medium">
            Row {activeScanEntry.rowNumber ?? '?'} of {scanEntries.length}
            {activeScanEntry.fileName && ` · ${activeScanEntry.fileName}`}
          </span>
          <button
            type="button"
            onClick={() => {
              const idx = scanEntries.findIndex((e) => e.id === activeScanEntryId);
              if (idx < scanEntries.length - 1) onActiveScanEntryIdChange(scanEntries[idx + 1].id);
            }}
            disabled={scanEntries.findIndex((e) => e.id === activeScanEntryId) >= scanEntries.length - 1}
            className="px-2 py-1 text-xs text-gray-400 hover:text-white disabled:opacity-30 disabled:cursor-not-allowed"
          >
            Next Row →
          </button>
        </div>
      )}

      {/* Header fields */}
      <div className="bg-gray-800 border border-gray-700 rounded-lg p-3 grid grid-cols-2 gap-3">
        <div>
          <div className="text-xs text-gray-500 mb-1">Transaction Date</div>
          <SmartDatePicker value={txnDate} onChange={setTxnDate} />
        </div>
        <div>
          <div className="text-xs text-gray-500 mb-1">Doc Number <span className="text-gray-600">(optional)</span></div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={docNumber}
            onChange={(e) => setDocNumber(e.target.value)}
            placeholder="Auto-generated by QB"
          />
        </div>
        <div className="col-span-2">
          <div className="text-xs text-gray-500 mb-1">Memo / Private Note</div>
          <input
            className="w-full bg-gray-900 border border-gray-600 text-white text-xs rounded px-2 py-1.5 focus:border-cyan-500 focus:outline-none"
            value={privateNote}
            onChange={(e) => setPrivateNote(e.target.value)}
            placeholder={`Nest sync — ${txnDate}`}
          />
        </div>
        <div className="flex items-center gap-2">
          <input
            type="checkbox"
            id="je-adjusting"
            checked={isAdjusting}
            onChange={(e) => setIsAdjusting(e.target.checked)}
            className="rounded border-gray-600"
          />
          <label htmlFor="je-adjusting" className="text-xs text-gray-400 cursor-pointer">
            Adjusting Entry (period-end)
          </label>
        </div>
      </div>

      {/* Balance bar + column toggle */}
      <div className="flex items-center gap-3">
        <div className={`flex items-center gap-2 text-xs px-3 py-1.5 rounded-lg flex-1 ${
          isBalanced
            ? 'bg-green-900/30 border border-green-800 text-green-400'
            : 'bg-red-900/30 border border-red-800 text-red-400'
        }`}>
          <span>{isBalanced ? '✅ Balanced' : '⚠️ Unbalanced'}</span>
          <span className="font-mono text-gray-400">
            Dr ${fmt(totalDebits)} / Cr ${fmt(totalCredits)}
          </span>
          {!isBalanced && (
            <span className="font-mono text-red-400">diff ${fmt(Math.abs(diff))}</span>
          )}
        </div>
        <label className="flex items-center gap-1.5 text-xs cursor-pointer select-none shrink-0">
          <input
            type="checkbox"
            checked={consolidate}
            onChange={(e) => setConsolidate(e.target.checked)}
            className="rounded border-gray-600"
          />
          <span className={consolidate ? 'text-cyan-400' : 'text-gray-500'}>
            🔗 Consolidate
          </span>
        </label>
        <div className="relative flex-shrink-0">
          <button
            onClick={() => setShowColMenu((x) => !x)}
            className="flex items-center gap-1 text-xs text-gray-400 hover:text-gray-200 border border-gray-700 hover:border-gray-500 px-2.5 py-1.5 rounded transition-colors"
          >
            <span>☰</span>
            <span>Columns</span>
          </button>
          {showColMenu && (
            <div className="absolute right-0 top-full mt-1 z-20 bg-gray-800 border border-gray-600 rounded-lg shadow-lg p-2 min-w-36">
              {ALL_COLUMNS.map((col) => (
                <label key={col.key} className="flex items-center gap-2 py-1 px-1 hover:bg-gray-700/50 rounded cursor-pointer">
                  <input
                    type="checkbox"
                    checked={colVis[col.key]}
                    onChange={(e) => setColVis((prev) => ({ ...prev, [col.key]: e.target.checked }))}
                    className="rounded border-gray-600"
                  />
                  <span className="text-xs text-gray-300">{col.label}</span>
                </label>
              ))}
            </div>
          )}
        </div>
      </div>
      {unmappedCount > 0 && (
        <div className="flex items-center gap-2 text-xs px-3 py-1.5 rounded-lg bg-amber-900/30 border border-amber-700 text-amber-300">
          <span>⚠️ {unmappedCount} unmapped line{unmappedCount !== 1 ? 's' : ''}</span>
          <span className="text-amber-500">— assign QB accounts before syncing</span>
        </div>
      )}

      {consolidate && rawDisplayLines.length < lines.length && (
        <div className="flex items-center gap-2 text-xs px-3 py-1.5 rounded-lg bg-cyan-900/20 border border-cyan-800 text-cyan-400">
          <span>🔗 Consolidated {lines.length} lines → {rawDisplayLines.length} lines</span>
          <span className="text-cyan-600">— {lines.length - rawDisplayLines.length} merged</span>
        </div>
      )}

      {autoBalanced && (
        <div className="flex items-center gap-2 text-xs px-3 py-1.5 rounded-lg bg-yellow-900/20 border border-yellow-700 text-yellow-300">
          <span>⚖️ Auto-balanced ${autoBalanced.amount.toFixed(2)} rounding difference</span>
          <span className="text-yellow-500">— adjusted largest line to make debits = credits</span>
        </div>
      )}

      {/* Full column table — scrollable container */}
      <div className="bg-gray-800 border border-gray-700 rounded-lg overflow-hidden">
        <div style={{ overflowX: 'auto', overflowY: 'auto', maxHeight: 380 }}>
          <table className="w-full text-xs border-collapse" style={{ minWidth: 580 }}>
            <thead>
              <tr className="border-b border-gray-700 bg-gray-700/50">
                <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ width: 32 }}>#</th>
                {colVis.account && (
                  <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ minWidth: 160 }}>Account</th>
                )}
                {colVis.name && (
                  <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ minWidth: 120 }}>Name</th>
                )}
                {colVis.description && (
                  <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ minWidth: 130 }}>Description</th>
                )}
                {colVis.class && (
                  <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ minWidth: 100 }}>Class</th>
                )}
                {colVis.taxCode && (
                  <th className="text-gray-400 font-medium text-left px-2 py-2" style={{ minWidth: 90 }}>Tax Code</th>
                )}
                {colVis.debit && (
                  <th className="text-gray-400 font-medium text-right px-2 py-2" style={{ width: 96 }}>Debit</th>
                )}
                {colVis.credit && (
                  <th className="text-gray-400 font-medium text-right px-2 py-2" style={{ width: 96 }}>Credit</th>
                )}
                <th className="text-gray-400 font-medium text-center px-1 py-2" style={{ width: 32 }}></th>
              </tr>
            </thead>
            <tbody>
              {effectiveDisplayLines.map((line, idx) => (
                <TableRow
                  key={line.localId}
                  line={line}
                  index={idx}
                  colVis={colVis}
                  accountOptions={accountOptions}
                  entityOptions={entityOptions}
                  classOptions={classOptions}
                  taxCodeOptions={taxCodeOptions}
                  accounts={accounts}
                  onChange={(patch) => updateLine(line.localId, patch)}
                  onRemove={() => removeLine(line.localId)}
                  canRemove={effectiveDisplayLines.length > 1}
                />
              ))}
            </tbody>
            <tfoot>
              <tr className="border-t border-gray-600 bg-gray-700/30 font-semibold">
                <td className="px-2 py-2 text-gray-500">{effectiveDisplayLines.length}</td>
                {colVis.account && <td></td>}
                {colVis.name && <td></td>}
                {colVis.description && (
                  <td className="px-2 py-2 text-gray-500">
                    {effectiveDisplayLines.length} line{effectiveDisplayLines.length !== 1 ? 's' : ''}
                  </td>
                )}
                {colVis.class && <td></td>}
                {colVis.taxCode && <td></td>}
                {colVis.debit && (
                  <td className="px-2 py-2 text-right font-mono text-blue-300 font-bold">
                    ${fmt(totalDebits)}
                  </td>
                )}
                {colVis.credit && (
                  <td className="px-2 py-2 text-right font-mono text-emerald-300 font-bold">
                    ${fmt(totalCredits)}
                  </td>
                )}
                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      {/* Add line */}
      <button
        type="button"
        onClick={() => setLines((prev) => [...prev, newLine()])}
        className="w-full text-xs text-gray-500 hover:text-gray-300 border border-dashed border-gray-700 hover:border-gray-500 py-1.5 rounded-lg transition-colors"
      >
        + Add Line
      </button>

      {/* Messages */}
      {duplicateWarning && (
        <ErrorCard
          variant="warning"
          message={duplicateWarning}
          onDismiss={() => setDuplicateWarning(null)}
          onRetry={handleForceSync}
        />
      )}
      {error && (
        <div className="bg-red-900/40 border border-red-700 text-red-300 text-xs rounded-lg px-3 py-2">
          {error}
        </div>
      )}
      {syncResult && (
        <div className="bg-green-900/40 border border-green-700 text-green-300 text-xs rounded-lg px-3 py-2 space-y-1.5">
          <div>✅ Journal Entry created — <span className="font-mono">{syncResult.id}</span> ({syncResult.txnDate})</div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => navigator.clipboard.writeText(syncResult.id).catch(() => {})}
              className="text-xs text-cyan-400 hover:text-cyan-300 border border-cyan-800 hover:border-cyan-600 px-2 py-0.5 rounded transition-colors"
            >
              Copy ID
            </button>
            <a
              href={`${status.environment === 'sandbox' ? 'https://app.sandbox.qbo.intuit.com' : 'https://app.qbo.intuit.com'}/app/journal?txnId=${syncResult.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs text-cyan-400 hover:underline"
            >
              View in QuickBooks ↗
            </a>
          </div>
        </div>
      )}

      {/* Action buttons */}
      <div className="flex gap-2">
        <button
          type="button"
          onClick={handleClearAll}
          className="px-3 py-2 text-xs text-red-400 border border-red-800 hover:bg-red-900/20 rounded-lg transition-colors"
        >
          Clear All
        </button>
        <button
          onClick={() => void handleSync()}
          disabled={syncing || !isBalanced || !allMapped || effectiveDisplayLines.every((l) => !l.accountId)}
          className="flex-1 py-2.5 bg-green-600 hover:bg-green-500 disabled:bg-gray-700 disabled:text-gray-500 text-white text-sm font-bold rounded-lg transition-colors"
        >
          {syncing
            ? 'Syncing to QuickBooks…'
            : !isBalanced
              ? '⚠️ Journal Entry is Unbalanced'
              : !allMapped
                ? `⚠️ ${unmappedCount} unmapped line${unmappedCount !== 1 ? 's' : ''} — assign all accounts`
                : '⚡ Sync to QuickBooks'}
        </button>
      </div>
    </div>
  );
}

// ── TableRow ──────────────────────────────────────────────────────────────────

interface TableRowProps {
  line: LineItem;
  index: number;
  colVis: Record<ColKey, boolean>;
  accountOptions: SelectOption[];
  entityOptions: SelectOption[];
  classOptions: SelectOption[];
  taxCodeOptions: SelectOption[];
  accounts: QBAccount[];
  onChange: (patch: Partial<LineItem>) => void;
  onRemove: () => void;
  canRemove: boolean;
}

function TableRow({
  line, index, colVis,
  accountOptions, entityOptions, classOptions, taxCodeOptions, accounts,
  onChange, onRemove, canRemove,
}: TableRowProps) {
  return (
    <tr className={`border-b border-gray-700/60 ${index % 2 === 1 ? 'bg-gray-800/40' : ''}`}>
      <td className="px-2 py-1 text-gray-600 text-center text-xs">{index + 1}</td>

      {colVis.account && (
        <td className="px-1 py-1" style={{ minWidth: 160, maxWidth: 220 }}>
          <div className="relative">
            {!line.accountId && (
              <span className="absolute -top-3 left-0 text-[10px] bg-amber-900 text-amber-300 px-1 rounded z-10">
                ⚠️ UNMAPPED
              </span>
            )}
            <SearchableSelect
              options={accountOptions}
              value={line.accountId}
              onChange={(v) => {
                const acct = accounts.find((a) => a.Id === v);
                onChange({ accountId: v, accountName: acct?.FullyQualifiedName ?? '' });
              }}
              placeholder="Account…"
            />
          </div>
        </td>
      )}

      {colVis.name && (
        <td className="px-1 py-1" style={{ minWidth: 120, maxWidth: 180 }}>
          <SearchableSelect
            options={entityOptions}
            value={line.entityVal}
            onChange={(v) => onChange({ entityVal: v })}
            placeholder="Name…"
          />
        </td>
      )}

      {colVis.description && (
        <td className="px-1 py-1" style={{ minWidth: 130 }}>
          <input
            className="w-full bg-gray-900 border border-gray-700 text-gray-300 text-xs rounded px-2 py-1 focus:border-cyan-500 focus:outline-none"
            value={line.description}
            onChange={(e) => onChange({ description: e.target.value })}
            placeholder="Description…"
            maxLength={4000}
          />
        </td>
      )}

      {colVis.class && (
        <td className="px-1 py-1" style={{ minWidth: 100, maxWidth: 140 }}>
          <SearchableSelect
            options={classOptions}
            value={line.classId}
            onChange={(v) => onChange({ classId: v })}
            placeholder={classOptions.length === 0 ? '—' : 'Class…'}
            disabled={classOptions.length === 0}
          />
        </td>
      )}

      {colVis.taxCode && (
        <td className="px-1 py-1" style={{ minWidth: 90, maxWidth: 130 }}>
          <SearchableSelect
            options={taxCodeOptions}
            value={line.taxCodeId}
            onChange={(v) => onChange({ taxCodeId: v })}
            placeholder={taxCodeOptions.length === 0 ? '—' : 'Tax…'}
            disabled={taxCodeOptions.length === 0}
          />
        </td>
      )}

      {colVis.debit && (
        <td className="px-1 py-1" style={{ width: 96 }}>
          <input
            type="number"
            min="0"
            step="0.01"
            className="w-full bg-gray-900 border border-gray-700 text-blue-300 text-xs rounded px-2 py-1 text-right focus:border-blue-500 focus:outline-none font-mono"
            value={line.debit}
            placeholder="0.00"
            onChange={(e) => onChange({ debit: e.target.value, credit: e.target.value ? '' : line.credit })}
          />
        </td>
      )}

      {colVis.credit && (
        <td className="px-1 py-1" style={{ width: 96 }}>
          <input
            type="number"
            min="0"
            step="0.01"
            className="w-full bg-gray-900 border border-gray-700 text-emerald-300 text-xs rounded px-2 py-1 text-right focus:border-emerald-500 focus:outline-none font-mono"
            value={line.credit}
            placeholder="0.00"
            onChange={(e) => onChange({ credit: e.target.value, debit: e.target.value ? '' : line.debit })}
          />
        </td>
      )}

      <td className="px-1 py-1 text-center" style={{ width: 32 }}>
        {canRemove && (
          <button
            type="button"
            onClick={onRemove}
            className="text-gray-600 hover:text-red-400 transition-colors"
            title="Remove line"
          >
            🗑️
          </button>
        )}
      </td>
    </tr>
  );
}

import React, { useState, useCallback, useEffect } from 'react';
import { useAuth } from './hooks/useAuth';
import { useQuickBooks } from './hooks/useQuickBooks';
import { useLocations } from './hooks/useLocations';
import { QBContextProvider } from './contexts/QBContext';
import { hasPerm } from './lib/permissions';
import { api } from './lib/api';
import { getOnboardingState, type OnboardingState } from './lib/onboarding';
import { OnboardingBanner } from './components/OnboardingBanner';
import LoginView from './components/LoginView';
import ChangePasswordView from './components/ChangePasswordView';
import TabNav from './components/TabNav';
import ScanView from './components/ScanView';
import MappingView from './components/MappingView';
import JournalEntryPreview from './components/JournalEntryPreview';
import BillPreviewForm from './components/BillPreviewForm';
import VendorCreditPreviewForm from './components/VendorCreditPreviewForm';
import CheckPreviewForm from './components/CheckPreviewForm';
import QBDataView from './components/QBDataView';
import SyncView from './components/SyncView';
import SettingsView from './components/SettingsView';
import HelpPanel from './components/HelpPanel';
import PartnersTab from './components/PartnersTab';
import RequestsTab from './components/RequestsTab';
import MyTeamTab from './components/MyTeamTab';
import ActivityTab from './components/ActivityTab';
import RulesView from './components/RulesView';
import DashboardView from './components/DashboardView';
import AdminDashboard from './components/AdminDashboard';
import { UserDashboard } from './components/UserDashboard';
import BillPaymentView from './components/BillPaymentView';
import AdminsTab from './components/AdminsTab';
import UsersTab from './components/UsersTab';
import LocationsTab from './components/LocationsTab';
import ProductCatalogView from './components/ProductCatalogView';
import type { TabId, ScanData, ScanEntry, Template } from '../types';
import { ToastProvider, ToastContainer } from './components/Toast';

const ROLE_META: Record<string, { icon: string; color: string }> = {
  OWNER: { icon: '👑', color: 'bg-yellow-500/20 text-yellow-300 border-yellow-600' },
  ADMIN: { icon: '🛡️', color: 'bg-cyan-500/20 text-cyan-300 border-cyan-600' },
  ACCOUNTANT: { icon: '📊', color: 'bg-blue-500/20 text-blue-300 border-blue-600' },
  STAFF: { icon: '🧑‍💻', color: 'bg-green-500/20 text-green-300 border-green-600' },
  VIEWER: { icon: '👁️', color: 'bg-gray-500/20 text-gray-300 border-gray-600' },
};

export default function App() {
  const { jwt, user, loading, login, logout } = useAuth();
  const [currentTab, setCurrentTab] = useState<TabId>('dashboard');
  const [scanData, setScanData] = useState<ScanData | null>(null);
  const [scanRecordId, setScanRecordId] = useState<string | null>(null);
  const [scanEntries, setScanEntries] = useState<ScanEntry[]>([]);
  const [activeScanEntryId, setActiveScanEntryId] = useState<string | null>(null);
  const [invoiceFile, setInvoiceFile] = useState<File | null>(null);
  const [selectedLocationId, setSelectedLocationId] = useState<string>('');
  const [selectedTemplateForScan, setSelectedTemplateForScan] = useState<Template | null>(null);
  const [showExcelImportModal, setShowExcelImportModal] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [showEmailVerificationBanner, setShowEmailVerificationBanner] = useState(true);
  const [deferredMappings, setDeferredMappings] = useState(false);
  const [deferredSynced, setDeferredSynced] = useState(false);
  const [hasSavedMappings, setHasSavedMappings] = useState(false);
  const [hasSyncedBefore, setHasSyncedBefore] = useState(false);
  const { status: qbStatus } = useQuickBooks(jwt);
  const { locations, loading: locationsLoading } = useLocations(jwt);

  // After password change: refresh auth state by re-fetching session
  const handlePasswordChanged = useCallback(async () => {
    // Force reload to re-run useAuth session fetch with updated mustChangePassword
    window.location.reload();
  }, []);

  useEffect(() => {
    if (scanData === null) {
      setScanRecordId(null);
    }
  }, [scanData]);

  const activeScanEntry = scanEntries.find((entry) => entry.id === activeScanEntryId) ?? null;
  const currentScanSource = activeScanEntry?.source;
  const noScanData = !scanData && !activeScanEntry;
  const isIncompatibleTemplate = selectedTemplateForScan &&
    (selectedTemplateForScan.transactionType === 'BILL' || selectedTemplateForScan.transactionType === 'VENDOR_CREDIT') &&
    currentScanSource === 'pos';

  const activeLocations = locations.filter((location) => location.isActive);
  const dropdownLocations = activeLocations.length > 0 ? activeLocations : locations;

  useEffect(() => {
    if (user?.emailVerified) {
      setShowEmailVerificationBanner(false);
    }
  }, [user?.emailVerified]);

  useEffect(() => {
    if (!jwt || !user || user.role !== 'OWNER' || dropdownLocations.length === 0) return;
    if (selectedLocationId === '') {
      setSelectedLocationId(dropdownLocations[0]?.id);
    }
    let active = true;

    const loadMappings = async () => {
      try {
        const results = await Promise.allSettled(
          locations.map((location) => api.getMappings(jwt, location.id).then((mappings) => mappings.length)),
        );
        if (!active) return;

        const hasMappings = results.some(
          (result) => result.status === 'fulfilled' && result.value > 0,
        );

        if (hasMappings) {
          setHasSavedMappings(true);
        }
      } catch {
        // ignore mapping load failures; onboarding can still update later
      }
    };

    void loadMappings();
    return () => {
      active = false;
    };
  }, [jwt, user, locations]);

  useEffect(() => {
    if (!jwt || !user || user.role !== 'OWNER') return;
    let active = true;

    const loadOwnerStats = async () => {
      try {
        const stats = await api.getOwnerStats(jwt);
        if (!active) return;

        if (stats.totalSynced > 0) {
          setHasSyncedBefore(true);
        }
      } catch {
        // ignore stats load failures; onboarding can still update later
      }
    };

    void loadOwnerStats();
    return () => {
      active = false;
    };
  }, [jwt, user]);

  const onboardingState = getOnboardingState({
    qbStatus: qbStatus || null,
    hasLocations: locations.length > 0,
    hasMappings: deferredMappings || hasSavedMappings,
    hasSynced: deferredSynced || hasSyncedBefore,
  });

  if (loading) {
    return (
      <div className="flex items-center justify-center bg-gray-900" style={{ width: '100vw', height: '100vh' }}>
        <div className="text-gray-500 text-sm">Loading…</div>
      </div>
    );
  }

  if (!user) {
    return (
      <ToastProvider>
        <div className="flex flex-col bg-gray-900 text-white" style={{ width: '100vw', height: '100vh', overflow: 'hidden' }}>
          <div className="flex items-center justify-between px-4 py-2 border-b border-slate-700">
            <span className="text-sm font-semibold text-white">Nest</span>
          </div>
          <LoginView onLogin={login} />
          <ToastContainer />
        </div>
      </ToastProvider>
    );
  }

  // Disabled account — full-screen message
  if (user.status === 'DISABLED') {
    return (
      <div className="flex flex-col items-center justify-center bg-gray-900 text-white" style={{ width: '100vw', height: '100vh' }}>
        <div className="text-center px-6">
          <div className="text-4xl mb-3">🚫</div>
          <h2 className="text-lg font-semibold text-white mb-2">Account Disabled</h2>
          <p className="text-sm text-gray-400 mb-5">Your account has been disabled. Please contact your administrator.</p>
          <button onClick={logout} className="px-4 py-2 bg-slate-700 text-gray-300 rounded-lg text-sm hover:bg-slate-600">
            Sign Out
          </button>
        </div>
      </div>
    );
  }

  // Must change password — show password change flow
  if (user.mustChangePassword) {
    return (
      <ToastProvider>
        <div className="flex flex-col bg-gray-900 text-white" style={{ width: '100vw', height: '100vh', overflow: 'hidden' }}>
          <div className="flex items-center justify-between px-4 py-2 border-b border-slate-700">
            <span className="text-sm font-semibold text-white">Nest</span>
            <button onClick={logout} className="text-xs text-gray-500 hover:text-gray-300">Sign Out</button>
          </div>
          <ChangePasswordView jwt={jwt!} onDone={handlePasswordChanged} />
          <ToastContainer />
        </div>
      </ToastProvider>
    );
  }

  // Determine visible tabs based on role + permissions
  const role = user.role;
  const visibleTabs: TabId[] = [];

  if (role === 'OWNER') {
    visibleTabs.push('dashboard', 'scan', 'mappings', 'products', 'rules', 'preview', 'data', 'sync', 'payments', 'partners', 'requests', 'admins', 'users', 'locations', 'activity', 'settings');
  } else if (role === 'ADMIN') {
    visibleTabs.push('dashboard', 'my-team');
    if (hasPerm(user, 'scan', 'write')) visibleTabs.push('scan');
    if (hasPerm(user, 'map', 'write')) visibleTabs.push('mappings', 'products', 'rules', 'preview');
    if (hasPerm(user, 'sync', 'execute')) visibleTabs.push('data', 'sync', 'payments');
    if (hasPerm(user, 'locations', 'write')) visibleTabs.push('locations');
    visibleTabs.push('settings');
  } else {
    visibleTabs.push('dashboard');
    if (hasPerm(user, 'scan', 'write')) visibleTabs.push('scan');
    if (hasPerm(user, 'map', 'write')) visibleTabs.push('mappings', 'products', 'rules', 'preview');
    if (hasPerm(user, 'sync', 'execute')) visibleTabs.push('data', 'sync', 'payments');
    if (hasPerm(user, 'locations', 'write')) visibleTabs.push('locations');
    visibleTabs.push('settings');
  }

  // Default to first tab if currentTab not visible
  const effectiveTab = visibleTabs.includes(currentTab) ? currentTab : (visibleTabs[0] ?? 'settings');

  return (
    <ToastProvider>
    <QBContextProvider jwt={jwt!}>
      <div className="flex flex-col bg-gray-900 text-white" style={{ width: '100vw', height: '100vh', overflow: 'hidden' }}>
        {/* Expired trial warning banner */}
        {user.status === 'EXPIRED' && (
          <div className="px-4 py-2 bg-yellow-900/60 border-b border-yellow-700 text-xs text-yellow-300 text-center flex-shrink-0">
            <p className="font-medium">Your access has expired.</p>
            {user.customExpiryMessage && (
              <p className="mt-1">{user.customExpiryMessage}</p>
            )}
            <p className="mt-1">Contact your admin or owner for renewal.</p>
          </div>
        )}

        {/* Grace period warning banner */}
        {user.status === 'GRACE_PERIOD' && (
          <div className="px-4 py-2 bg-yellow-900/60 border-b border-yellow-700 text-xs text-yellow-300 text-center flex-shrink-0">
            ⚠ Your write access expires soon. Contact your administrator.
          </div>
        )}

        {/* Time-bombed restricted banner */}
        {user.status === 'TIME_BOMBED' && (
          <div className="px-4 py-2 bg-red-900/60 border-b border-red-700 text-xs text-red-300 text-center flex-shrink-0">
            🚫 Your write access has been restricted. You have view-only access. Contact your administrator.
          </div>
        )}

        {/* Header */}
        <div className="grid items-center px-4 py-2 bg-gray-800 border-b border-gray-700 flex-shrink-0" style={{ gridTemplateColumns: '1fr auto 1fr' }}>
          <div className="flex items-center gap-1.5">
            <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded border text-[10px] font-medium ${ROLE_META[user.role]?.color ?? 'bg-gray-500/20 text-gray-300 border-gray-600'}`}>
              {ROLE_META[user.role]?.icon} {user.role}
            </span>
            {user.status === 'EXPIRED' && (
              <span className="inline-flex items-center px-1 py-0.5 rounded border text-[10px] font-medium bg-yellow-900/40 text-yellow-400 border-yellow-600">⚠</span>
            )}
            <span className="text-[9px] text-gray-500 truncate max-w-[90px]">{user.email}</span>
          </div>
          <div className="flex items-center justify-center gap-2">
            <span className="text-cyan-400 font-bold text-base tracking-tight">🪹 Nest</span>
            <span className="text-gray-500 text-xs">Restaurant Financial Automation</span>
            <span className="text-gray-600 text-[10px]" title="Created by John Paul O. Escuadra">· by JP Escuadra</span>
          </div>
          <div className="flex justify-end gap-2">
            <select
              value={selectedLocationId}
              onChange={(e) => setSelectedLocationId(e.target.value)}
              disabled={locationsLoading || dropdownLocations.length === 0}
              className="h-8 bg-gray-700 border border-gray-600 text-gray-200 text-[10px] px-2 rounded"
            >
              {locationsLoading || dropdownLocations.length === 0 ? (
                <option value="">{locationsLoading ? 'Loading locations...' : 'No locations'}</option>
              ) : (
                dropdownLocations.map((location) => (
                  <option key={location.id} value={location.id}>{location.name}</option>
                ))
              )}
            </select>
            <button
              onClick={() => setShowHelp(true)}
              className="text-gray-500 hover:text-gray-300 text-sm transition-colors"
              title="Help"
              aria-label="Open help"
            >
              ❓
            </button>
          </div>
        </div>

        {user && !user.emailVerified && showEmailVerificationBanner && (
          <div className="px-4 py-2 bg-yellow-900/60 border-b border-yellow-700 text-xs text-yellow-300 flex items-center justify-between gap-3">
            <div>
              <p className="font-medium">⚠️ Please verify your email. Check your inbox or resend from Settings.</p>
            </div>
            <button
              onClick={() => setShowEmailVerificationBanner(false)}
              className="text-yellow-200 hover:text-white text-xs"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Tab Nav */}
        <TabNav currentTab={effectiveTab} onTabChange={setCurrentTab} visibleTabs={visibleTabs} />

        {/* Onboarding banner for owner users */}
        {role === 'OWNER' && onboardingState.step > 0 && (
          <OnboardingBanner state={onboardingState} onNavigate={setCurrentTab} />
        )}

        {/* Pipeline progress indicator — shown when scan data is loaded */}
        {(scanData !== null || scanEntries.length > 0) && (() => {
          const steps: { id: string; label: string }[] = [
            { id: 'scan', label: '① Scan' },
            { id: 'mappings', label: '② Map' },
            { id: 'rules', label: '③ Rules' },
            { id: 'preview', label: '④ Preview' },
            { id: 'sync', label: '⑤ Sync' },
          ];
          const currentIdx = steps.findIndex((s) => s.id === effectiveTab);
          return (
            <div className="flex items-center justify-center gap-1 px-4 py-1 bg-gray-800/50 border-b border-gray-700 flex-shrink-0">
              {steps.map((step, i) => {
                const stepIdx = steps.findIndex((s) => s.id === step.id);
                const isCurrent = effectiveTab === step.id;
                const isCompleted = currentIdx > stepIdx;
                return (
                  <React.Fragment key={step.id}>
                    <span className={`text-[10px] font-medium px-1 rounded ${
                      isCurrent ? 'text-cyan-400' : isCompleted ? 'text-green-400' : 'text-gray-600'
                    }`}>
                      {step.label}
                    </span>
                    {i < steps.length - 1 && <span className="text-gray-700 text-[10px]">→</span>}
                  </React.Fragment>
                );
              })}
            </div>
          );
        })()}

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto" style={{ overflowX: 'hidden', minHeight: 0 }}>
          {effectiveTab === 'scan' && (
            <ScanView
              jwt={jwt!}
              scanData={scanData}
              onScanData={setScanData}
              onClearScanData={() => setScanData(null)}
              onScanRecordId={setScanRecordId}
              locationId={selectedLocationId || null}
              onboardingStep={onboardingState.step}
              selectedTemplate={selectedTemplateForScan}
              onOpenExcelImportModal={() => setShowExcelImportModal(true)}
              onTabChange={setCurrentTab}
              scanEntries={scanEntries}
              setScanEntries={setScanEntries}
              activeScanEntryId={activeScanEntryId}
              setActiveScanEntryId={setActiveScanEntryId}
              activeScanEntry={activeScanEntry}
              invoiceFile={invoiceFile}
              setInvoiceFile={setInvoiceFile}
            />
          )}
          {effectiveTab === 'mappings' && (
            <MappingView
              jwt={jwt!}
              selectedLocationId={selectedLocationId}
              onLocationChange={setSelectedLocationId}
              scanData={scanData}
              scanEntries={scanEntries}
              activeScanEntry={activeScanEntry}
              onActiveScanEntryIdChange={setActiveScanEntryId}
              onTabChange={setCurrentTab}
              onboardingStep={onboardingState.step}
              onHasMappings={() => setDeferredMappings(true)}
              onSelectedTemplateChange={setSelectedTemplateForScan}
              initialTemplate={selectedTemplateForScan}
              showExcelImportModal={showExcelImportModal}
              setShowExcelImportModal={setShowExcelImportModal}
            />
          )}
          {effectiveTab === 'products' && (
            <ProductCatalogView jwt={jwt!} />
          )}
          {effectiveTab === 'preview' && (
            noScanData || !selectedTemplateForScan ? (
              <div className="p-6 rounded-lg border border-orange-500 bg-orange-950/50 text-orange-200 text-sm">
                Select a template and scan data to preview the transaction.
              </div>
            ) : isIncompatibleTemplate ? (
              <div className="p-6 rounded-lg border border-yellow-500 bg-yellow-950/50 text-yellow-200 text-sm">
                <div className="font-semibold text-white">Template Not Compatible</div>
                <p className="mt-2">
                  Bill and Vendor Credit templates are designed for invoice scans (image/PDF). Your current scan is from POS data. Please use a Journal Entry template for POS scans, or scan an invoice to use this template.
                </p>
              </div>
            ) : selectedTemplateForScan.transactionType === 'BILL' ? (
              <BillPreviewForm
                jwt={jwt!}
                scanData={scanData}
                activeScanEntry={activeScanEntry}
                selectedLocationId={selectedLocationId}
                scanRecordId={scanRecordId}
                selectedTemplate={selectedTemplateForScan}
                onNavigateToPayments={() => setCurrentTab('payments')}
              />
            ) : selectedTemplateForScan.transactionType === 'VENDOR_CREDIT' ? (
              <VendorCreditPreviewForm
                jwt={jwt!}
                scanData={scanData}
                activeScanEntry={activeScanEntry}
                selectedLocationId={selectedLocationId}
                scanRecordId={scanRecordId}
                selectedTemplate={selectedTemplateForScan}
              />
            ) : selectedTemplateForScan.transactionType === 'CHEQUE' ? (
              <CheckPreviewForm
                jwt={jwt!}
                scanData={scanData}
                activeScanEntry={activeScanEntry}
                selectedLocationId={selectedLocationId}
                scanRecordId={scanRecordId}
                selectedTemplate={selectedTemplateForScan}
              />
            ) : (
              <JournalEntryPreview
                jwt={jwt!}
                scanData={scanData}
                scanEntries={scanEntries}
                activeScanEntry={activeScanEntry}
                activeScanEntryId={activeScanEntryId}
                onActiveScanEntryIdChange={setActiveScanEntryId}
                selectedLocationId={selectedLocationId}
                scanRecordId={scanRecordId}
              />
            )
          )}
          {effectiveTab === 'payments' && (
            <BillPaymentView
              jwt={jwt!}
              selectedLocationId={selectedLocationId}
            />
          )}
          {effectiveTab === 'data' && (
            <QBDataView />
          )}
          {effectiveTab === 'sync' && (
