// ── Decoded mapping ───────────────────────────────────────────────────────────

export interface DecodedMapping {
  sourceField: string;
  accountId: string;
  postingType: 'Debit' | 'Credit';
  classId?: string;
  description?: string;
  keepSeparate?: boolean;
}

