export function guessPostingType(field: string): 'debit' | 'credit' {
  const section = field.toLowerCase().split('.')[0]?.trim() ?? '';
  const lower = field.toLowerCase();

  // Cash Activity: most items are Debit (cash coming in), but tips paid out are Credit
  if (section === 'cash activity') {
    if (/credit.*tip|non-cash tip|tip.*paid/i.test(lower)) return 'credit';
    return 'debit';
  }

  // Tips: most items are Credit (tips received), but tips paid out are Debit
  if (section === 'tips') {
    if (/paid out|paid.*out|cash.*tip/i.test(lower)) return 'debit';
    return 'credit';
  }

  // Payments: always Debit (money coming IN)
  if (/^(payments|cash summary)$/.test(section)) return 'debit';

  // Revenue / Sales: always Credit
  if (/^(revenue|net sales|sales category|revenue center|service daypart|dining option|service mode|deferred)$/.test(section)) return 'credit';

  // Tax, Service Charge: Credit
  if (/^(tax|service charge)$/.test(section)) return 'credit';

  // Discount, Void: Debit (contra-revenue)
  if (/^(discount|void)$/.test(section)) return 'debit';

  // Unpaid Orders: Debit (Accounts Receivable)
  if (/^(unpaid orders)$/.test(section)) return 'debit';

  // Fallback: keyword matching on the full field name
  if (/cash|credit card|debit card|gift card|discount|refund|void|comp\b|net sales|total/.test(lower)) return 'debit';
  if (/sales|revenue|income|tax|tip|gratuity|fee|charge/.test(lower)) return 'credit';

  return 'debit';
}

// ── decodeMapping ─────────────────────────────────────────────────────────────
// Parses targetMemo JSON for overrides, normalizes postingType and classId.

export function decodeMapping(m: Mapping): DecodedMapping {
  let postingType: 'Debit' | 'Credit' = (m.postingType === 'Debit' || m.postingType === 'Credit') ? m.postingType : 'Credit';
  let classId: string | undefined = m.targetClass ?? undefined;
  let keepSeparate: boolean = m.keepSeparate ?? false;

  try {
    if (m.targetMemo) {
      const extra = JSON.parse(m.targetMemo) as { postingType?: string; classId?: string; keepSeparate?: boolean };
      if (m.postingType === undefined && (extra.postingType === 'Debit' || extra.postingType === 'Credit')) {
        postingType = extra.postingType;
      }
      if (m.keepSeparate === undefined && extra.keepSeparate !== undefined) {
        keepSeparate = extra.keepSeparate;
      }
    }
  } catch { /* ignore */ }

  return {
    sourceField: m.sourceField,
    accountId: m.targetAccount,
    postingType,
    classId,
    description: m.targetDescription ?? undefined,
    keepSeparate,
  };
}

// ── buildJEPayload ────────────────────────────────────────────────────────────
// Converts raw scan data + mappings + QB accounts into a QBJournalLineItem[]
// ready to POST to /api/quickbooks/journal-entry or /sync-batch.
// Entity refs are NOT included — those are manual per-line UI overrides.

import { fuzzyMatch, FUZZY_LOW_CONFIDENCE_THRESHOLD } from './fuzzy-matcher';
import type { ProductMapping, ExtractedLineItem } from '../../types';

export function extractLineItems(params: {
  lineItems: Record<string, string>[];
  columnMappings: Record<string, unknown>;
  productMappings: ProductMapping[];
  defaultPostingType: 'Credit' | 'Debit';
}): ExtractedLineItem[] {
  const {
    lineItems,
    columnMappings,
    productMappings,
    defaultPostingType,
  } = params;

  const productColumn = String(columnMappings.productColumn ?? '').trim();
  const amountColumn = String(columnMappings.amountColumn ?? '').trim();
  const descriptionColumn = String(columnMappings.descriptionColumn ?? '').trim();
  const classColumn = String(columnMappings.classColumn ?? '').trim();
  const taxCodeColumn = String(columnMappings.taxCodeColumn ?? '').trim();

  if (!productColumn || !amountColumn) {
    return [];
  }

  const normalizedMappings = productMappings.map((mapping) => ({
    key: mapping.productName?.trim().toLowerCase(),
    originalKey: mapping.productName?.trim(),
    mapping,
  }));

  return lineItems.reduce<ExtractedLineItem[]>((acc, row) => {
    const productName = String(row[productColumn] ?? '').trim();
    const amountRaw = String(row[amountColumn] ?? '').trim();
    const amountValue = parseFloat(amountRaw.replace(/[^0-9.-]+/g, ''));

    if (!productName || Number.isNaN(amountValue) || amountValue === 0) {
      return acc;
    }

    const description = descriptionColumn
      ? String(row[descriptionColumn] ?? '').trim() || productName
      : productName;

    const classId = classColumn
      ? String(row[classColumn] ?? '').trim() || null
      : null;

    const taxCodeId = taxCodeColumn
      ? String(row[taxCodeColumn] ?? '').trim() || null
      : null;

    const normalizedProductName = productName.trim().toLowerCase();
    const exactMatch = normalizedMappings.find((entry) => entry.key === normalizedProductName);
    let matchedMapping = exactMatch?.mapping ?? null;
    let fuzzyMatched = false;
    let lowConfidence = false;

    if (!matchedMapping && normalizedMappings.length > 0) {
      const candidates = normalizedMappings.map((entry) => entry.originalKey);
      const result = fuzzyMatch(productName, candidates);
      if (result) {
        matchedMapping = normalizedMappings[result.index].mapping;
        fuzzyMatched = true;
        lowConfidence = result.score < FUZZY_LOW_CONFIDENCE_THRESHOLD;
      }
    }

    const accountId = matchedMapping?.accountId ?? '';
    const accountName = '';
    const postingType = matchedMapping?.postingType ?? defaultPostingType;
    const matched = Boolean(matchedMapping);

    acc.push({
      productName,
      amount: amountValue,
      description,
      classId,
      taxCodeId,
      accountId,
      accountName,
      postingType,
      matched,
      fuzzyMatched,
      lowConfidence: fuzzyMatched ? lowConfidence : undefined,
    });

    return acc;
  }, []);
}

export function getAutoFillSummary(items: ExtractedLineItem[]): {
  total: number;
  mapped: number;
  unmapped: number;
} {
  const total = items.length;
  const mapped = items.filter((item) => item.matched).length;
  const unmapped = total - mapped;
  return { total, mapped, unmapped };
}
